const storyWalletToggle=$('story-wallet-toggle');
const storyWalletDetails=$('story-wallet-details');
const storyWalletWrap=$('story-wallet-wrap');
if(storyWalletToggle&&storyWalletDetails&&storyWalletWrap){
 const walletChoiceKey='bible-unfolded-wallet-expanded';
 let blockWalletClick=false,walletAnim=null;
  // Truly hidden when closed: the only persistent control is a chevron in the chapter header.
  // Opening the drawer moves the artwork down rather than painting over the image.
  const setStoryWalletOpen=(open,instant=false)=>{
   const oldOpen=storyWalletToggle.getAttribute('aria-expanded')==='true';
   if(walletAnim){walletAnim.cancel();walletAnim=null}
   storyWalletToggle.setAttribute('aria-expanded',String(open));
   storyWalletToggle.setAttribute('aria-label',open?'Hide Insight Tokens, Points and rank':'Show Insight Tokens, Points and rank');
   storyWalletToggle.title=open?'Hide score':'Show score';
   if(open){storyWalletWrap.hidden=false;storyWalletDetails.hidden=false}
   if(!instant&&open!==oldOpen&&storyWalletWrap.animate){
    const h=storyWalletWrap.scrollHeight;
    walletAnim=storyWalletWrap.animate(open?[{height:'0px',opacity:0},{height:h+'px',opacity:1}]:[{height:h+'px',opacity:1},{height:'0px',opacity:0}],{duration:240,easing:'cubic-bezier(.2,.7,.2,1)'});
    walletAnim.onfinish=()=>{walletAnim=null;if(!open){storyWalletDetails.hidden=true;storyWalletWrap.hidden=true}};
    
   }else if(!open){storyWalletDetails.hidden=true;storyWalletWrap.hidden=true}
   try{localStorage.setItem(walletChoiceKey,open?'1':'0')}catch(_){}
  };
  try{if(localStorage.getItem(walletChoiceKey)==='1')setStoryWalletOpen(true,true)}catch(_){}
  let swipeStart=null,swipeHandled=false;
  // Tapping the icon always works. Swiping down on it opens the drawer;
  // swiping up on either the icon or open panel closes the drawer.
  storyWalletToggle.onclick=()=>{if(!swipeHandled)setStoryWalletOpen(storyWalletToggle.getAttribute('aria-expanded')!=='true');};
  for(const swipeArea of [storyWalletToggle,storyWalletWrap]){
   swipeArea.addEventListener('pointerdown',e=>{
    if(e.pointerType==='mouse'&&e.button!==0)return;
    swipeStart={id:e.pointerId,x:e.clientX,y:e.clientY};
   },{passive:true});
   swipeArea.addEventListener('pointerup',e=>{
    if(!swipeStart||e.pointerId!==swipeStart.id)return;
    const dx=e.clientX-swipeStart.x,dy=e.clientY-swipeStart.y;swipeStart=null;
    if(Math.abs(dy)<23||Math.abs(dy)<Math.abs(dx)*1.3)return;
    swipeHandled=true;
    setStoryWalletOpen(dy>0);
    setTimeout(()=>{swipeHandled=false},300);
   });
   swipeArea.addEventListener('pointercancel',()=>{swipeStart=null});
   // On touch browsers vertical scroll may cancel pointerup; use a passive fallback.
   let touchY=null,touchX=null;
   swipeArea.addEventListener('touchstart',e=>{
    if(e.touches.length===1){touchY=e.touches[0].clientY;touchX=e.touches[0].clientX}
   },{passive:true});
   swipeArea.addEventListener('touchend',e=>{
    if(touchY===null)return;
    const t=e.changedTouches[0],dy=t.clientY-touchY,dx=t.clientX-touchX;
    touchY=null;
    if(Math.abs(dy)<23||Math.abs(dy)<Math.abs(dx)*1.3)return;
    swipeHandled=true;setStoryWalletOpen(dy>0);
    setTimeout(()=>{swipeHandled=false},300);
   },{passive:true});
  }
}
