const X_SAVE='bible-unfolded-crosswords-v14';
let crossProgress=CROSS_PACKS.map(()=>[]),crossReplay=false,crossReplayProgress=[],crossPack=0,crossCurrent=0,crossSelected=[],crossPointer=null,crossDrag=false,crossOrigin=[0,0],crossReset=null;
try{const old=JSON.parse(localStorage.getItem(X_SAVE)||'null');if(old&&Array.isArray(old.solved))crossProgress=CROSS_PACKS.map((_,i)=>Array.isArray(old.solved[i])?old.solved[i].filter(w=>typeof w==='string'):[])}catch(e){}
crossProgress=CROSS_PACKS.map((_,i)=>Array.isArray(crossProgress[i])?crossProgress[i]:[]);
function crossSave(){try{localStorage.setItem(X_SAVE,JSON.stringify({solved:crossProgress}))}catch(e){}}
function crossWords(){return CROSS_PACKS[crossPack].words}
function crossSolved(){return crossReplay?crossReplayProgress:crossProgress[crossPack]}
function mixCrossLetters(word){
 const letters=word.split('');if(letters.length<3)return word;
 const isEasy=a=>{const doubled=a+a,reverse=a.split('').reverse().join(''),back=reverse+reverse;
 return doubled.includes(word)||back.includes(word)};
 for(let trial=0;trial<36;trial++){
  for(let i=letters.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[letters[i],letters[j]]=[letters[j],letters[i]]}
  const a=letters.join('');if(a!==word&&!isEasy(a))return a;
 }
 return letters.join('');
}
function mixCrossPack(i){CROSS_PACKS[i].words.forEach(w=>w.scramble=mixCrossLetters(w.word))}

function crossChooseAvailable(){const words=crossWords();if(!words.length)return 0;const ix=words.findIndex(w=>!crossSolved().includes(w.word));return ix===-1?0:ix}
function crossPick(i){crossCurrent=i;crossSelected=[];crossRender()}
