function renderCrossPicker(){
 // The complete picker remains scrollable on short Android and iPhone viewports.
 const subtitles=['The first creative periods','Moses’ early life','Living things and the creative periods','The garden and its first inhabitants','The decision in Eden','Cain and Abel','Noah and the Flood'];
 $('cross-pack-list').innerHTML=CROSS_PACKS.map((p,i)=>{
  const solved=(crossProgress[i]||[]).length,total=p.words.length;
  const done=solved===total;
  return `<button class="mode-card cross-pack-card" data-pack="${i}"><span class="mode-icon">${String(i+1).padStart(2,'0')}</span><span><strong>${p.title}${i>=7?' <em class="trail-new-tag">NEW</em>':''}</strong><small>${subtitles[i]||p.reference} · ${solved}/${total} solved</small><span class="cross-pack-progress"><i style="width:${Math.round(100*solved/total)}%"></i></span></span><b>${done?'✓':'›'}</b></button>`
 }).join('');
 $('cross-pack-list').querySelectorAll('[data-pack]').forEach(b=>b.onclick=()=>crossOpenBook(+b.dataset.pack));updateWallet();
}
function crossOpen(){openCrossPick()}
function crossOpenBook(i){startAudio();stopWatch();hideAll();closeMenu();closeDialog();crossReplay=false;crossReplayProgress=[];crossPack=i;crossSelected=[];mixCrossPack(i);crossCurrent=crossChooseAvailable();$('crossword-screen').hidden=false;crossRender();document.title='Bible Unfolded · '+CROSS_PACKS[i].title+' Crossword';syncMusic()}

