 let k=0;return w.word.split('').map((ch,i)=>{
  if(Object.prototype.hasOwnProperty.call(entry.anchors,i))return `<span class="cross-fixed" title="Letter revealed by crossing word">${ch}</span>`;
  const ix=sel[k++];return `<span class="${ix===undefined?'cross-blank':'cross-typed'}">${ix===undefined?'·':w.scramble[ix]}</span>`;
 }).join('');
