 html+='<div id="xword-answer" class="xword-answer" aria-live="polite">'+crossAnswerText(selected)+'</div>';
 html+=`<div class="cross-entry-note">${Object.keys(entry.anchors).length?Object.keys(entry.anchors).length+' crossing letter'+(Object.keys(entry.anchors).length===1?'':'s')+' already filled—solve the blanks!':'Use the crossing words as you solve the grid.'}</div>`;
 if(entry.positions.length){html+='<div id="xword-wheel" class="xword-wheel"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><path class="bu3822-halo" d=""></path><path class="bu3822-ribbon" id="xword-trace" d=""></path><circle class="bu3822-tip" r="1.7" cx="50" cy="50" visibility="hidden"></circle></svg>';
  for(let i=0;i<selected.scramble.length;i++){const a=i*Math.PI*2/selected.scramble.length-Math.PI/2;html+=`<button class="xword-letter" data-xletter="${i}" style="--px:${50+Math.cos(a)*39}%;--py:${50+Math.sin(a)*39}%">${selected.scramble[i]}</button>`}
  html+='</div>';
 }else html+='<div class="cross-confirm-text">Every letter is already supplied by crossing words!</div><button id="cross-confirm" class="xword-next">Confirm Answer ✓</button>';
 html+='<div class="xword-note" id="xword-note"></div><div class="xword-actions"><button id="xword-hint">✦ Hint</button><button id="xword-reset">↶ Undo</button></div>';
 html+='<details class="cross-all-clues"><summary>View all clues and crossings</summary>'+words.map((w,i)=>`<button data-cross-pick="${i}" class="${i===crossCurrent?'active':''}"><b>${numbers[i]} ${w.dir==='across'?'Across':'Down'}</b><span>${w.clue}</span><em>${crossSolved().includes(w.word)?'✓ Solved':w.word.length+' letters'}</em></button>`).join('')+'</details>';
 html+='<a class="cross-source cross-source-play" href="'+(pack.source||crossSource(crossPack))+'" target="_blank" rel="noopener noreferrer">Read this passage on JW.org ↗</a>';
 parent.innerHTML=html;
 parent.querySelectorAll('[data-cross-pick]').forEach(b=>b.onclick=()=>crossPick(+b.dataset.crossPick));
 parent.querySelectorAll('.xword-cell[data-words]').forEach(b=>b.onclick=()=>{
  const inds=b.dataset.words.split(',').map(Number),prefer=inds.find(i=>!crossSolved().includes(words[i].word))??inds[0];crossPick(prefer);
 });
