 document.querySelectorAll('[data-wallet="true"]').forEach(el=>el.innerHTML=markup);const sc=$('story-coin-count'),sp=$('story-point-count');if(sc)sc.textContent=economy.coins.toLocaleString();if(sp)sp.textContent=economy.points.toLocaleString();
