// Shared scripture reference dialog — never navigate before the player chooses the linked verses.
function bu3898ScriptureDialog(references){
 const refs=(Array.isArray(references)?references:[]).filter(r=>r&&String(r.reference||'').trim());
 const previous=document.getElementById('bu3898-scripture-layer');if(previous)previous.remove();
 const layer=document.createElement('div');layer.id='bu3898-scripture-layer';layer.setAttribute('role','presentation');
 const dialog=document.createElement('div');dialog.className='bu3898-scripture-dialog';dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-label','Bible passage');
 const close=document.createElement('button');close.type='button';close.className='bu3898-close';close.setAttribute('aria-label','Close');close.textContent='×';
 const heading=document.createElement('h2');heading.textContent='Read the Bible passage';
 const helper=document.createElement('p');helper.textContent='These are the verses for this discovery. Tap the passage to open JW.org.';
 dialog.append(close,heading,helper);
 const list=document.createElement('div');list.className='bu3898-passage-list';
 for(const ref of refs){const a=document.createElement('a');a.className='bu3898-passage-link';a.textContent='📖 '+ref.reference+'  ↗';a.href=(typeof ref.url==='string'&&/^https:\/\/(www\.)?jw\.org\//i.test(ref.url))?ref.url:scriptureUrl(ref.reference);a.target='_blank';a.rel='noopener noreferrer';list.append(a);}
 if(!refs.length){const note=document.createElement('p');note.textContent='The exact verse reference for this discovery is not available.';list.append(note);}
 dialog.append(list);layer.append(dialog);document.body.append(layer);
 const escape=e=>{if(e.key==='Escape'){e.preventDefault();exit();}};
 const exit=()=>{layer.remove();document.removeEventListener('keydown',escape);};
 close.addEventListener('click',exit);layer.addEventListener('click',e=>{if(e.target===layer)exit();});document.addEventListener('keydown',escape);close.focus();
}
function scriptureUrl(reference){
 const books=['Genesis','Exodus','Leviticus','Numbers','Deuteronomy','Joshua','Judges','Ruth','1 Samuel','2 Samuel','1 Kings','2 Kings','1 Chronicles','2 Chronicles','Ezra','Nehemiah','Esther','Job','Psalms','Proverbs','Ecclesiastes','Song of Solomon','Isaiah','Jeremiah','Lamentations','Ezekiel','Daniel','Hosea','Joel','Amos','Obadiah','Jonah','Micah','Nahum','Habakkuk','Zephaniah','Haggai','Zechariah','Malachi','Matthew','Mark','Luke','John','Acts','Romans','1 Corinthians','2 Corinthians','Galatians','Ephesians','Philippians','Colossians','1 Thessalonians','2 Thessalonians','1 Timothy','2 Timothy','Titus','Philemon','Hebrews','James','1 Peter','2 Peter','1 John','2 John','3 John','Jude','Revelation'];
 const value=String(reference||'').trim().replace(/^Psalm(?=\s+\d)/i,'Psalms');const name=books.sort((a,b)=>b.length-a.length).find(b=>value.toLowerCase().startsWith(b.toLowerCase()+' '));
 if(!name)return 'https://www.jw.org/en/library/bible/nwt/';const m=value.slice(name.length).trim().match(/^(\d+)/);
 if(!m)return 'https://www.jw.org/en/library/bible/nwt/';
 const slug=name.toLowerCase().replace(/\s+/g,'-');return `https://www.jw.org/en/library/bible/nwt/books/${slug}/${m[1]}/`;
}
const STORY_RIDDLES={EARTH:'Our home planet, beneath the heavens.',LIGHT:'Without it, nothing on earth would be visible.',SKY:'Look above the clouds and open waters.',LAND:'Ground that is no longer covered by the sea.',PLANTS:'Some provide food, flowers, or shade.',LIGHTS:'They help us distinguish seasons, days, and years.',SWARM:'Picture a huge number of sea creatures moving together.',BIRDS:'Creatures with wings that fly overhead.',DOMESTIC:'Animals that people commonly keep or raise.',SUBDUE:'To bring something under control or make use of it responsibly.',GARDEN:'A cultivated, beautiful place full of growing things.',RIVER:'It flows, carrying fresh water through the land.',HELPER:'Someone who assists or complements another.'};
function hintNext(key,word,clue,display){
 // Respect all previous purchases while never revealing an almost-complete solution.
 const level=Math.max(0,Math.min(3,Number(economy.hints[key]||0)));
 const answer=String(word||'').trim().toUpperCase();
 const len=answer.length;
 let message='';
 if(level===0){
  message='Clue: '+String(clue||'Read the scripture above and look for the answer.').trim();
  economy.hints[key]=1;
 } else if(level===1){
  if(!canSpend(15,true))return;
  message=`−15 Insight Tokens · First letter: ${answer.slice(0,1)}. Use the linked scripture to finish the word.`;
  economy.hints[key]=2;
 } else if(level===2){
  if(!canSpend(30,true))return;
  message=`−30 Insight Tokens · First two letters: ${answer.slice(0,Math.min(2,len-1)).split('').join(' ')}. Use the letters already on the board to finish.`;
  economy.hints[key]=3;
 } else {
  message=`All purchased hints used. First two letters: ${answer.slice(0,Math.min(2,len-1)).split('').join(' ')}. Check the scripture above.`;
 }
 saveEconomy();if(display){display.textContent=message;display.setAttribute('role','status')}else notify(message);
}
