function purchase(id,cost){
 bu3824RefreshWallet();bu3824MergeEntitlements();
 if(economy.purchases.includes(id)){
  if(BU_WHEEL_IDS.includes(id))setWheelTheme(id);else openRewards();return;
 }
 if(!Number.isFinite(cost)||cost<0)return;
 if(economy.coins<cost){notify('You need '+(cost-economy.coins)+' more Insight Tokens. Keep playing to earn them!');return;}
 // One atomic wallet record: cost and permanent ownership are saved together.
 // A failed save rolls back the transaction instead of taking someone's Insight Tokens.
 const before=JSON.parse(JSON.stringify(economy));
 economy.coins-=cost;
 economy.purchases=[...new Set([...(economy.purchases||[]),id])];
 if(BU_WHEEL_IDS.includes(id)){
  economy.equippedWheel=id;
  economy.wheelPurchaseHistory=[...(Array.isArray(economy.wheelPurchaseHistory)?economy.wheelPurchaseHistory:[]),{id,coinsSpent:cost,when:new Date().toISOString()}].slice(-40);
 }
 if(!saveEconomy()){
  economy=before;bu3824MergeEntitlements();
  notify('Purchase not saved. No Insight Tokens charged. Please check browser storage.');updateWallet();return;
 }
 updateWallet();playCoinFx('spend');
 if(BU_WHEEL_IDS.includes(id)){
  document.documentElement.classList.toggle('gold-wheel',id==='goldwheel');
  document.documentElement.classList.toggle('moon-wheel',id==='moonwheel');
  document.documentElement.classList.toggle('sea-wheel',id==='seawheel');
  notify('✦ Wheel style unlocked and equipped!');openRewards();return;
 }
 notify('✦ Reward unlocked!');openRewards();
}
