/* v2.0 cinematic navigation and progress portability — does not modify Watch Stories internals */
(function initCinematicShell(){
 const dashboard=$('home-hero');
 if(dashboard)dashboard.style.setProperty('--cover-scene',`url("${ART.eden_garden}")`);
 document.documentElement.style.setProperty('--cin-scene',`url("${ART.genesis_plants}")`);
 const coverArt=(selector,asset)=>{const el=document.querySelector(selector);if(el)el.style.backgroundImage=`linear-gradient(180deg,#071b2430,#071b2442),url("${asset}")`};
 coverArt('#home .art-story',ART.genesis_humans);
 coverArt('#home .art-watch',ART.moses_river);
 coverArt('#home .art-cross',ART.genesis_animals);
 document.querySelectorAll('.mode-card.story').forEach(el=>el.style.setProperty('--mode-scene',`url("${ART.genesis_humans}")`));
 document.querySelectorAll('.mode-card.watch').forEach(el=>el.style.setProperty('--mode-scene',`url("${ART.moses_river}")`));
 document.querySelectorAll('.mode-card.cross').forEach(el=>el.style.setProperty('--mode-scene',`url("${ART.genesis_animals}")`));
 const homeOpen=(id,action)=>{const el=$(id);if(el)el.addEventListener('click',()=>{startAudio();action();})};
 homeOpen('home-story',()=>{openJourney();rewardPopup()});
 homeOpen('home-watch',()=>{openWatchPick();rewardPopup()});
 homeOpen('home-cross',()=>{openCrossPick();rewardPopup()});
 homeOpen('home-books',openLevels);
 homeOpen('home-journey',openJourney);
 homeOpen('home-gallery',openGallery);
 homeOpen('home-shop',openRewards);
 homeOpen('home-rewards',openRewards);
 homeOpen('home-help',()=>{openDialog('help')});
 // If the presentation is open in landscape, all three modes work without an extra menu.
 /* v3.8.8 — Complete progress backup: old v1 JSON files remain importable. */
 const bu388SaveKey=k=>typeof k==='string'&&/^(?:bible-unfolded|story-trails)-[a-z0-9_.-]+$/i.test(k)&&k.length<=160;
 function bu388AppKeys(){const keys=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(bu388SaveKey(k))keys.push(k)}return keys;}
 const exported=$('save-export'),imported=$('save-import'),picker=$('save-file');
 if(exported)exported.onclick=()=>{
  try{
   const saved={};for(const key of bu388AppKeys()){const value=localStorage.getItem(key);if(value!==null)saved[key]=value;}
   const data=JSON.stringify({format:'BibleUnfoldedSave',version:1,exportedAt:new Date().toISOString(),keys:saved},null,2);
   const blob=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
   a.href=url;a.download='Bible_Unfolded_Progress_Backup.json';a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);
   notify('Complete progress backup prepared. Keep the JSON file safe.');
  }catch(e){notify('Backup failed: '+e.message)}
 };
 if(imported&&picker){imported.onclick=()=>picker.click();picker.onchange=async()=>{
  const file=picker.files&&picker.files[0];if(!file)return;
  try{
   if(file.size>2000000)throw new Error('This backup file is too large.');
   const data=JSON.parse(await file.text());
   if(data.format!=='BibleUnfoldedSave'||data.version!==1||!data.keys||typeof data.keys!=='object'||Array.isArray(data.keys))throw new Error('This is not a Bible Unfolded backup.');
   const keys=Object.keys(data.keys);
   if(!keys.length||keys.length>100||keys.some(k=>!bu388SaveKey(k)||typeof data.keys[k]!=='string'||data.keys[k].length>300000))throw new Error('The backup contains invalid saved data.');
   if(!confirm('Import this backup? It replaces the current saved progress on this device. Export your current progress first if you want to keep it.'))return;
   // Prevent the phone's pagehide/visibility handlers from writing OLD game state
   // back on top of this freshly imported progress before reload.
   window.__bu388SkipCheckpoint=true;
   const previous={};for(const k of bu388AppKeys())previous[k]=localStorage.getItem(k);
   try{
    Object.keys(previous).forEach(k=>localStorage.removeItem(k));
    keys.forEach(k=>localStorage.setItem(k,data.keys[k]));
   }catch(err){
    // Best-effort rollback if a phone runs out of storage partway through import.
    try{for(const k of bu388AppKeys())localStorage.removeItem(k);for(const [k,v] of Object.entries(previous))localStorage.setItem(k,v)}catch(_){}
    throw err;
   }
   location.reload();
  }catch(e){window.__bu388SkipCheckpoint=false;notify('Import failed: '+e.message)}finally{picker.value='';}
 };}
 })();

