const BU28_REVIEW_KEY='bible-unfolded-review-v28';
let bu28ReviewBook=null,bu28ReviewStep=0,bu28ReviewScore=0,bu28ReviewAnswered=false;
let bu28ReviewBest={};try{bu28ReviewBest=JSON.parse(localStorage.getItem(BU28_REVIEW_KEY)||'{}');if(!bu28ReviewBest||typeof bu28ReviewBest!=='object')bu28ReviewBest={}}catch(_){bu28ReviewBest={}}
function bu28StartReview(book){
 if(!completedChapters[book]){notify('Finish this account to unlock its review.');return}
 if(!BU28_REVIEW[book])return;
 bu28ReviewBook=book;bu28ReviewStep=0;bu28ReviewScore=0;bu28ReviewAnswered=false;
 $('bu28-review').hidden=false;bu28RenderReview();$('bu28-review-close').focus();
}
function bu28CloseReview(){ $('bu28-review').hidden=true;bu28ReviewBook=null; }
function bu28RenderReview(){
 const target=$('bu28-review-body'),book=bu28ReviewBook,questions=BU28_REVIEW[book];if(!book||!questions)return;
 if(bu28ReviewStep>=questions.length){
  const prev=Number(bu28ReviewBest[book]||0);bu28ReviewBest[book]=Math.max(prev,bu28ReviewScore);
  try{localStorage.setItem(BU28_REVIEW_KEY,JSON.stringify(bu28ReviewBest))}catch(_){}
  const passed=bu28ReviewScore>=3;
  const got=passed?awardOnce('review-v28-'+book,80,20,true):false;
  if(passed&&got){playCoinFx('earn');playVictoryCheer()}
  target.innerHTML=`<div class="bu28-review-summary"><p class="bu28-review-progress">ACCOUNT REVIEW COMPLETE</p><strong>${bu28ReviewScore} / ${questions.length}</strong><p>${passed?'Beautiful work! You remembered the major lessons.': 'Nice effort! Read the account and try again to strengthen your recall.'}</p><p class="bu28-review-sub">${got?'+80 Points and +20 Insight Tokens earned!':passed?'Your one-time reward was already collected.':'Score at least 3 of 4 to earn 80 Points and 20 Insight Tokens (one time only).'}<br>Best score: ${bu28ReviewBest[book]} of ${questions.length}</p><button class="bu28-review-action" id="bu28-review-again">Play Again</button><button class="bu28-review-action" id="bu28-review-done" style="background:#174451;color:#f8dcaa;border:1px solid #9e8c65">Back to Chapter</button></div>`;
  $('bu28-review-again').onclick=()=>bu28StartReview(book);$('bu28-review-done').onclick=bu28CloseReview;return;
 }
 const q=questions[bu28ReviewStep];bu28ReviewAnswered=false;
 target.innerHTML=`<p class="bu28-review-progress">QUESTION ${bu28ReviewStep+1} OF ${questions.length} · ${book.toUpperCase()}</p><h3>${q.q}</h3><div class="bu28-review-choices">${q.choices.map((opt,i)=>`<button type="button" class="bu28-review-choice" data-review-choice="${i}">${String.fromCharCode(65+i)} · ${opt}</button>`).join('')}</div><div class="bu28-review-feedback" id="bu28-review-feedback" role="status" aria-live="polite" hidden></div><button class="bu28-review-action" id="bu28-review-next" hidden>${bu28ReviewStep===questions.length-1?'See Results':'Next Question →'}</button>`;
 target.querySelectorAll('[data-review-choice]').forEach(b=>b.onclick=()=>bu28ChooseReview(+b.dataset.reviewChoice));
 $('bu28-review-next').onclick=()=>{bu28ReviewStep++;bu28RenderReview()};
}
function bu28ChooseReview(i){
 if(bu28ReviewAnswered)return;bu28ReviewAnswered=true;
 const q=BU28_REVIEW[bu28ReviewBook][bu28ReviewStep],correct=i===q.correct;
 if(correct)bu28ReviewScore++;
 $('bu28-review-body').querySelectorAll('[data-review-choice]').forEach(b=>{b.disabled=true;if(+b.dataset.reviewChoice===q.correct)b.classList.add('chosen')});
 const p=$('bu28-review-feedback');p.hidden=false;
 p.innerHTML=`<b>${correct?'✓ Correct!':'Not quite — here is the answer.'}</b><p>${q.explanation}</p><a href="${bu39226SourceLink(q)}" rel="noopener" target="_blank">Read ${q.ref} on JW.org ↗</a>`;
 $('bu28-review-next').hidden=false;
}
$('bu28-review-close').onclick=bu28CloseReview;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('bu28-review').hidden)bu28CloseReview()});


