const BU34_NAMES={genesis:['Creation','☀'],eden:['Eden','✿'],cain:['Cain & Abel','♧'],noah:['Noah','≋'],babel:['Babel','▥'],abraham:['Abraham','✧'],moses:['Moses','〰']};
const BU34_KEYS=Object.keys(BU34_NAMES);
const BU34_BANK=Object.fromEntries(BU34_KEYS.map(k=>[k,[...(BU28_REVIEW[k]||[]),...(BU34_EXTRAS[k]||[])]]));
const BU34_SEEN_KEY='bible-unfolded-trivia-v34';const BU34_TIPS_KEY='bible-unfolded-tips-v34';const BU34_AUDIO_KEY='bible-unfolded-immersive-v34';
let bu34Record={};try{bu34Record=JSON.parse(localStorage.getItem(BU34_SEEN_KEY)||'{}')||{}}catch(_){}
let bu34Tips={};try{bu34Tips=JSON.parse(localStorage.getItem(BU34_TIPS_KEY)||'{}')||{}}catch(_){}
let bu34Audio={celebrate:'full'};try{bu34Audio={...bu34Audio,...JSON.parse(localStorage.getItem(BU34_AUDIO_KEY)||'{}')}}catch(_){}
let bu34Quiz=null,bu34Feedback=false,bu34From='home',bu34FxTimer=0;
const bu34Esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function bu34Store(){try{localStorage.setItem(BU34_SEEN_KEY,JSON.stringify(bu34Record))}catch(_){}}
function bu34Shuffle(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function bu34Visible(){return !document.getElementById('bu34-trivia').hidden}
function bu34Home(){bu34Quiz=null;hideAll();closeDialog();closeMenu();document.getElementById('bu34-trivia').hidden=false;bu34RenderHome();document.title='Bible Unfolded · Bible Trivia';updateMusicState()}
function bu34RenderHome(){const body=document.getElementById('bu34-body');body.innerHTML=`<p class="bu34-intro">Pick a topic or jump into a quick round.<br>Every answer is based on a Bible passage on JW.org.</p><div class="bu34-modebar"><button data-qmode="quick">⚡ Quick Play<br><small>5 mixed questions</small></button><button data-qmode="challenge">✦ Challenge<br><small>10 mixed questions</small></button></div><h2 style="font:700 24px Georgia,serif;margin:0 0 13px">Choose a topic</h2><div class="bu34-categories">${BU34_KEYS.map(k=>`<button class="bu34-cat" data-topic="${k}"><span class="bu34-cat-icon">${BU34_NAMES[k][1]}</span>${BU34_NAMES[k][0]}<small>${BU34_BANK[k].length} questions · ${bu34Record['topic-'+k]?.rewarded?'✓ earned':'Play & earn'}</small></button>`).join('')}</div><p style="text-align:center;font-size:12px;color:#a5c5c9;margin:20px 0">Answers include explanations and direct Scripture links.<br>Insight Tokens and Points are awarded only once per challenge.</p>`;
body.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>bu34Start('topic',b.dataset.topic));body.querySelectorAll('[data-qmode]').forEach(b=>b.onclick=()=>bu34Start(b.dataset.qmode));body.scrollTop=0}
function bu34Start(type,topic='mixed'){
 const key=type==='topic'?'topic-'+topic:type;
 let all=type==='topic'?BU34_BANK[topic].map(x=>({...x,topic})):BU34_KEYS.flatMap(k=>BU34_BANK[k].map(x=>({...x,topic:k})));
 const count=type==='quick'?5:type==='challenge'?10:Math.min(7,all.length);
 const items=bu34Shuffle(all).slice(0,count).map(q=>{
  const order=bu34Shuffle(q.choices.map((v,i)=>({label:v,original:i})));
  return {...q,choices:order.map(x=>x.label),correct:order.findIndex(x=>x.original===q.correct)};
 });
 bu34Quiz={type,topic,key,items,step:0,score:0,answered:false,selected:-1};bu34Draw();
}
function bu34Draw(){
 const body=document.getElementById('bu34-body'),r=bu34Quiz,q=r.items[r.step];
 body.innerHTML=window.BUTriviaQuestionView.render(r,q,BU34_NAMES,bu34Esc,bu39226SourceLink);
 window.BUTriviaQuestionEvents.bind(body,bu34Choose,bu34Next,bu34Home);body.scrollTop=0;
}
// v3.8.49: gentle two-note incorrect-answer cue; respect existing Effects toggle/slider.
// Independent of music and announcer gain/ducking. Do not trigger harsh buzzers.
function bu3846WrongTone(){
 if(!context||!sfxOn||sfxVolume<=0)return;
 try{
  if(context.state==='suspended')context.resume().catch(()=>{});
  const base=context.currentTime,level=sfxVolume/100;
  [392,329.63].forEach((hz,i)=>{
   const start=base+i*.105,osc=context.createOscillator(),gain=context.createGain();
   osc.type='sine';osc.frequency.setValueAtTime(hz,start);
   gain.gain.setValueAtTime(.0001,start);
   gain.gain.exponentialRampToValueAtTime(.016*level,start+.025);
   gain.gain.exponentialRampToValueAtTime(.0001,start+.23);
   osc.connect(gain);gain.connect(context.destination);osc.start(start);osc.stop(start+.24);
   osc.onended=()=>{try{osc.disconnect();gain.disconnect()}catch(_){}};
  });
 }catch(_){/* Audio is optional; trivia must remain playable if sound is blocked. */}
}
function bu34Choose(i){const r=bu34Quiz;if(!r||r.answered)return;r.answered=true;r.selected=i;const q=r.items[r.step],correct=i===q.correct;if(correct){r.score++;playChime()}else bu3846WrongTone();
 const ans=document.querySelectorAll('#bu34-trivia [data-answer]');ans.forEach(b=>{b.disabled=true;const idx=+b.dataset.answer;if(idx===q.correct)b.classList.add('correct');else if(idx===i)b.classList.add('wrong')});
 const f=document.getElementById('bu34-feedback');f.hidden=false;f.innerHTML=`<b>${correct?'✓ Correct!':'The correct answer is: '+bu34Esc(q.choices[q.correct])}</b><div>${bu34Esc(q.explanation)}</div>`;document.getElementById('bu34-next').hidden=false;
}
function bu34Next(){if(!bu34Quiz?.answered)return;if(bu34Quiz.step+1<bu34Quiz.items.length){bu34Quiz.step++;bu34Quiz.answered=false;bu34Draw()}else bu34Finish()}
function bu34Finish(){const r=bu34Quiz,body=document.getElementById('bu34-body');const passed=r.score>=Math.ceil(r.items.length*.6),first=!bu34Record[r.key]?.rewarded,perfect=r.score===r.items.length;
 let coins=0,points=0;
 const t=bu34Record[r.key]||{best:0,played:0,rewarded:false};t.best=Math.max(t.best||0,r.score);t.played=(t.played||0)+1;
 if(first&&passed){points=r.type==='challenge'?160:r.type==='quick'?60:100;coins=r.type==='challenge'?45:r.type==='quick'?15:25;const credited=awardOnce('trivia-v34-'+r.key,points,coins,true);t.rewarded=true;if(!credited){points=0;coins=0}}
 bu34Record[r.key]=t;bu34Store();
 bu34Celebrate(perfect?'PERFECT ROUND!':passed?'WELL DONE!':'ROUND COMPLETE',true);
 body.innerHTML=`<div class="bu34-summary"><div style="font-size:46px">✦</div><h2>${perfect?'Perfect round!':passed?'Well played!':'Keep exploring!'}</h2><div class="big">${r.score}<span style="font-size:26px">/${r.items.length}</span></div><p>${passed?'Excellent recall!':'Every answer helps you learn something new.'}</p>${coins||points?`<p style="font-size:19px;color:#f6db9f;font-weight:800">+${points} Points · +${coins} Insight Tokens</p>`:!first?'<p>Your best score is saved. Replay rewards are not repeated.</p>':'<p>Score at least 60% next time to earn a new category reward.</p>'}<button id="bu34-retry" class="bu34-btn">Play Again ↻</button><button id="bu34-return" class="bu34-ghost">Trivia Categories</button></div>`;
 document.getElementById('bu34-retry').onclick=()=>bu34Start(r.type,r.topic);document.getElementById('bu34-return').onclick=bu34Home;body.scrollTop=0}
function bu34Back(){if(bu34Visible()){if(bu34Quiz)bu34Home();else focusHome()}else focusHome()}
document.getElementById('bu34-back').onclick=bu34Back;document.getElementById('bu34-menu').onclick=()=>{bu34From='trivia';openMenu()};document.getElementById('home-trivia').onclick=bu34Home;
// Decommission the old intermediary mode screen, but keep its IDs for save compatibility.
openModes=function(){focusHome()};document.getElementById('begin').onclick=()=>{startAudio();bu34Home()};
['journey-back','cross-pick-back','watch-pick-back','rewards-back','modes-back'].forEach(id=>{const el=document.getElementById(id);if(el)el.onclick=focusHome});
