// Stable audio mixing: switch tracks on entry, no artificial fade pumping or 90ms crossfades.
bu25AudioPulse=function(){const current=bu25Audio[bu25Current],enabled=musicOn&&musicUnlocked&&!document.hidden;for(const [key,p] of Object.entries(bu25Audio)){if(!p)continue;const should=enabled&&key===bu25Current;if(!should){if(!p.paused)p.pause();p.volume=0}else p.volume=Math.max(0,Math.min(1,musicVolume/100*.72))}};
updateMusicState=function(){if(!window.__bu25Ready)return;const enabled=musicOn&&musicUnlocked&&!document.hidden;const next=bu25Target();if(bu25Current!==next){bu25Current=next;bu25Old=null;bu25Status='';for(const [key,p] of Object.entries(bu25Audio)){if(!p)continue;if(key!==next&&!p.paused)p.pause()}try{bu25Audio[next].currentTime=0}catch(_){}}bu25AudioPulse();if(enabled)bu25Play(next);bu25UpdateStatus()};
if(bu25AudioTimer){clearInterval(bu25AudioTimer);bu25AudioTimer=null}
document.getElementById('setting-volume').addEventListener('input',()=>updateMusicState());
// Separate celebration strength setting; respects SFX volume and reduced-motion setting.
let bu34Line=document.createElement('label');bu34Line.className='setting-volume';bu34Line.innerHTML='<b>Celebrations</b><select id="bu34-celebrate" style="width:100%;padding:10px;background:#0a3240;color:#ffe4a5;border:1px solid #c8aa70;border-radius:10px"><option value="full">Full · confetti and cheering</option><option value="gentle">Gentle · small sparkle</option><option value="off">Off · no extra effects</option></select>';
const settings=document.getElementById('settings-dialog');const motion=document.getElementById('setting-motion')?.closest('label');if(settings&&motion)motion.before(bu34Line);
const bu34Select=document.getElementById('bu34-celebrate');bu34Select.value=['full','gentle','off'].includes(bu34Audio.celebrate)?bu34Audio.celebrate:'full';bu34Select.onchange=()=>{bu34Audio.celebrate=bu34Select.value;try{localStorage.setItem(BU34_AUDIO_KEY,JSON.stringify(bu34Audio))}catch(_){}};
function bu34Celebrate(label,large){if(bu34Audio.celebrate==='off')return;const gentle=bu34Audio.celebrate==='gentle';if(sfxOn&&sfxVolume>0){if(large&&!gentle){playVictoryCheer();trailCelebrateSound()}else if(large)playChime()}
 if(reduceMotion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const layer=document.getElementById('bu34-fx');layer.innerHTML='';layer.hidden=false;const n=gentle?10:large?65:15;for(let i=0;i<n;i++){const c=document.createElement('span');c.className='bu34-confetti';c.style.left=(Math.random()*100)+'%';c.style.background=['#f1cb77','#fff1ba','#8ddacc','#f6a97f'][i%4];c.style.animationDelay=(Math.random()*.55)+'s';c.style.animationDuration=(1.8+Math.random()*1.9)+'s';layer.appendChild(c)}if(large){let labelEl=document.createElement('div');labelEl.className='bu34-burst-text';labelEl.textContent=label;layer.appendChild(labelEl)}clearTimeout(bu34FxTimer);bu34FxTimer=setTimeout(()=>{layer.innerHTML='';layer.hidden=true},4000)}
// Replace the old six-button ending with a clear next chapter and restrained optional actions.
const bu34OldRender=render;
render=function(){bu34OldRender();if(document.getElementById('play').hidden)return;
 const panel=document.getElementById('gamepanel');if(mode==='clue'){
  const answer=document.getElementById('answer');if(answer&&answer.classList.contains('empty'))answer.textContent='';
  const hint=document.getElementById('hint');if(hint){hint.textContent='✦ Hint';hint.setAttribute('aria-label','Hint · may cost Insight Tokens')}
  const restart=document.getElementById('restart');if(restart)restart.textContent='↻';
 }else if(mode==='reveal'){const e=panel.querySelector('.reveal-pulse .eyebrow');if(e)e.textContent='DISCOVERY UNLOCKED';}
 else if(mode==='done'){
  const all=Array.from(panel.querySelectorAll('button'));const next=all.find(b=>b.id!=='toJourney' && /Next:/.test(b.textContent));
  const continueOld=document.getElementById('toJourney');if(continueOld){
   if(activeBook==='abraham'){
    continueOld.textContent='Next: Abraham and Lot →';
    continueOld.onclick=()=>bu3857Open('genesis_ep07');
   }else{
    continueOld.textContent=next?('Next Chapter →'):'Choose a Chapter →';
    if(next)continueOld.onclick=()=>next.click();
   }
  }
  const review=document.getElementById('bu28-review-open');if(review){review.textContent='Bible Trivia ↗';review.onclick=bu34Home}
  const replay=document.getElementById('playAgain');if(replay)replay.textContent='↻ Play Again';
  const story=document.getElementById('read-story');if(story)story.textContent='📖 Read Story';
  const back=document.getElementById('episodeBack');if(back)back.textContent='Chapters';
  const oldnext=next;if(oldnext)oldnext.hidden=true;
  panel.querySelector('.completion-caption')?.remove();
  const extras=[story,review,replay,back].filter(Boolean);const row=document.createElement('div');row.className='bu34-minor';if(replay)row.appendChild(replay);if(back)row.appendChild(back);
  if(continueOld)continueOld.after(row);
  for(const b of [story,review].filter(Boolean)){b.classList.add('bu34-link');row.after(b)}
  const watch=document.getElementById('watchComplete');if(watch)watch.hidden=true;
 }
};
