/* Bible Unfolded v3.5 — Family Worship: pass-and-play, wheel, guided reading, group games.
   Deliberately independent of single-player progression; main content and saves retained. */
const BU35_SAVE='bible-unfolded-family-v35';
// v3.8.25 - Persist content rotation independently of unfinished family sessions.
const BU3825_ROTATION_KEY='bible-unfolded-family-variety-v3825';
const bu3825Variety=(()=>{try{const v=JSON.parse(localStorage.getItem(BU3825_ROTATION_KEY)||'{}');return v&&typeof v==='object'&&v.decks&&typeof v.decks==='object'?v:{decks:{},mixes:{}}}catch(_){return {decks:{},mixes:{}}}})();
function bu3825Store(){try{localStorage.setItem(BU3825_ROTATION_KEY,JSON.stringify(bu3825Variety))}catch(_){}}
function bu3825Shuffle(source){const a=source.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
// A persisted shuffle bag avoids repeats until the topic's available questions are used.
// If the entire pool is exhausted, start a new shuffled cycle, avoiding an immediate repeat.
function bu3825Draw(key,count){
 if(!Number.isInteger(count)||count<1)return 0;
 let d=bu3825Variety.decks[key];
 if(!d||d.size!==count||!Array.isArray(d.queue))d={size:count,queue:[],last:-1};
 if(!d.queue.length){
  d.queue=bu3825Shuffle(Array.from({length:count},(_,i)=>i));
  if(count>1&&d.queue[0]===d.last){const i=d.queue.findIndex(v=>v!==d.last);if(i>0)[d.queue[0],d.queue[i]]=[d.queue[i],d.queue[0]];}
 }
 const n=d.queue.shift();d.last=n;bu3825Variety.decks[key]=d;bu3825Store();return n;
}
const BU3825_ACTIVITIES=['trivia','wheel','words','story','lightning'];
function bu3825Playlist(topic,minutes,style){
 const count=minutes>=30?5:minutes>=20?4:3;
 const key=topic+':'+minutes+':'+style;
 const recent=Array.isArray(bu3825Variety.mixes?.[key])?bu3825Variety.mixes[key]:[];
 let result=null,signature='';
 for(let tries=0;tries<36;tries++){
  const activities=bu3825Shuffle(BU3825_ACTIVITIES).slice(0,count);
  const layout=Math.random()<.48?[activities[0],'read',...activities.slice(1)]:['read',...activities];
  signature=layout.join('|');result=[...layout,'think','finish'];
  if(!recent.includes(signature))break;
 }
 if(!bu3825Variety.mixes||typeof bu3825Variety.mixes!=='object')bu3825Variety.mixes={};
 bu3825Variety.mixes[key]=[signature,...recent.filter(v=>v!==signature)].slice(0,7);
 bu3825Store();return result;
}

