// v3.8.29 — Family Worship replay quality and accessibility
function bu3829MixInDiscussions(phases,minutes){
 if(minutes<45)return phases;
 const flow=phases.filter(p=>p!=='think'&&p!=='finish');
 // Meaningful discussion breaks interleaved with activity: 2 at 45 minutes, 3 at 60.
 const breaks=minutes>=60?3:2,parts=[];
 const positions=breaks===3?[Math.max(2,Math.floor(flow.length/3)),Math.max(3,Math.floor(flow.length*2/3))]:[Math.max(2,Math.floor(flow.length/2))];
 flow.forEach((p,i)=>{parts.push(p);if(positions.includes(i+1))parts.push('think')});
 if(parts[parts.length-1]!=='think')parts.push('think');
 return [...parts,'finish'];
}
