function bu3827RelayPool(g){
 const main=BU35_STORY[g.topic]||GENESIS_BEATS;
 if(!g.familyPolishVersion)return main; // Keep old unfinished sessions stable.
 const required=g.people.length*bu35Rounds()*g.phases.filter(p=>p==='words'||p==='story').length;
 const seen=new Set(),unique=[];
 const add=(beat,bonus)=>{if(!beat||!beat.word||seen.has(beat.word))return;seen.add(beat.word);unique.push(bonus?{...beat,bu3827Bonus:true}:beat)};
 main.forEach(b=>add(b,false));
 if(unique.length>=required)return unique;
 // Reuse existing, sourced Bible-account words from related topics before the broad pool.
 const related=Object.values(BU3826_COLLECTIONS).find(c=>c.keys.includes(g.topic));
 if(related)for(const key of related.keys){if(key!==g.topic)(BU35_STORY[key]||[]).forEach(b=>add(b,true))}
 if(unique.length<required){for(const key of BU34_KEYS)(BU35_STORY[key]||[]).forEach(b=>add(b,true));}
 return unique;
}
function bu35Beat(){
 const g=bu35Game,beats=bu3827RelayPool(g);
 if(g.varietyVersion===1){
  const key=String(g.phase)+':'+bu35TurnNumber();
  if(!g.storyPicks)g.storyPicks={};
  if(!Array.isArray(g.usedRelayWords))g.usedRelayWords=[];
  if(!Number.isInteger(g.storyPicks[key])||g.storyPicks[key]>=beats.length){
   // Avoid repeating the same answer anywhere in the current family session,
   // even when Word Relay and Story Discovery draw from one content pool.
   const already=new Set(g.usedRelayWords);
   const unused=beats.map((b,i)=>i).filter(i=>!already.has(beats[i].word));
   let chosen;
   if(unused.length){
    // Stay on the chosen subject until its unique words are exhausted.
    const topical=unused.filter(i=>!beats[i].bu3827Bonus);
    const candidates=topical.length?topical:unused;
    const draw=bu3825Draw('family-relay:'+g.topic+':'+bu35Phase(),candidates.length);
    chosen=candidates[draw];
   }else{
    // Finite banks eventually recycle, but never repeat the immediately prior word when avoidable.
    const choices=beats.map((b,i)=>i).filter(i=>beats[i].word!==g.usedRelayWords[g.usedRelayWords.length-1]);
    chosen=(choices.length?choices:beats.map((_,i)=>i))[bu35Random((choices.length||beats.length))];
    g.usedRelayWords=[];
   }
   g.storyPicks[key]=chosen;
   g.usedRelayWords.push(beats[chosen].word);
   bu35Save();
  }
  const picked=beats[g.storyPicks[key]]||beats[0];
  if(g.topic==='jehovah'&&!g.familyPolishVersion&&Array.isArray(g.wordTiles)&&g.wordTiles.length){
    const sig=g.wordTiles.slice().sort().join('');
    const old=[['JEHOVAH','What personal name appears in Exodus 3:15?','Exodus 3:15'],['MERCY','Which quality does Exodus 34:6 highlight?','Exodus 34:6'],['LOVE','Which quality is central to 1 John 4:8?','1 John 4:8']];
    const matched=old.find(x=>x[0].split('').sort().join('')===sig);
    if(matched&&matched[0]!==picked.word){return {word:matched[0],clue:matched[1],reference:matched[2],fact:matched[0]+' is connected with '+matched[2]+'.',scene:null};}
  }
  return picked;
 }
 return beats[(bu35TurnNumber()+2)%beats.length];
}
function bu35Word(){
 // Use meaningful story-account vocabulary instead of generic crossword filler.
 const g=bu35Game,preferred=bu35Beat().word;
 // Keep already-started/unfinished Word Relay turns from old builds playable.
 if(bu35Phase()==='words'&&Array.isArray(g.wordTiles)&&g.wordTiles.length){
  const sameLetters=w=>String(w).split('').sort().join('')===g.wordTiles.slice().sort().join('');
  if(!sameLetters(preferred)){
   if(g.topic==='jehovah'){for(const w of ['JEHOVAH','MERCY','LOVE'])if(sameLetters(w))return w;}
   const oldMap={genesis:0,eden:1,cain:5,moses:3};
   const i=oldMap[g.topic];
   const old=Number.isInteger(i)?TRAIL_PACKS[i].words[(bu35TurnNumber()+2)%TRAIL_PACKS[i].words.length].word:preferred;
   if(sameLetters(old))return old;
  }
 }
 return preferred;
}
function bu35PrepareTurn(){const g=bu35Game;if(['story','words'].includes(bu35Phase())){const word=bu35Word();g.wordTiles=bu34Shuffle(word.split(''));g.wordSelection=[]}}
function bu35Trivia(){const g=bu35Game,q=bu35Question(),correct=g.choice===q.correct;
 return `<div class="bu35-card"><span class="bu35-kicker">${bu35Escape(g.people[g.turn])} · QUESTION ${bu35TurnNumber()+1}/${bu35TotalTurns()}</span><div class="bu35-question">${bu35Escape(q.q)}</div>${g.contentVersion===2?`<p class="bu35-level-meta">${bu35Escape(BU35_TOPICS[q.topic]?.name||BU35_TOPICS[g.topic]?.name||"Bible")}${q.difficulty?" · "+bu35Escape(q.difficulty.toUpperCase()):""}${q.__outside?" · Wider Bible mix":""}${q.__review?" · Topic review":""}</p>`:""}<p>${g.contentVersion===2?bu3832VerseLinks(q.ref):`<a class="bu35-scripture" target="_blank" rel="noopener noreferrer" href="${bu39226SourceLink(q)}">Read ${bu35Escape(q.ref)} on JW.org ↗</a>`}</p><div class="bu35-answers">${q.choices.map((opt,i)=>`<button class="bu35-answer ${g.answered&&i===q.correct?'correct':g.answered&&i===g.choice?'wrong':''}" data-answer="${i}" ${g.answered?'disabled':''}>${String.fromCharCode(65+i)} · ${bu35Escape(opt)}</button>`).join('')}</div>
 ${g.answered?`<div class="bu35-feedback"><b>${correct?'✓ Correct!':'Answer: '+bu35Escape(q.choices[q.correct])}</b>${bu35Escape(q.explanation)}</div><button class="bu35-btn" id="bu35-nextturn">${bu35LastTurn()?'Continue':'Pass to Next Player'} →</button>`:`<p class="bu35-muted">${g.hinted?'Family assistance enabled · correct answers earn half points.':'Ask a family member for help whenever you need it.'}</p><button class="bu35-outline" id="bu35-help">♡ Ask Family for Help</button><button class="bu35-soft" id="bu35-skip">Skip Question</button>`}</div>${bu35ScoreStrip()}`;
}
function bu3829FamilyPraise(g,{final=false}={}){
 if(typeof bu381Play!=='function'||!g||g!==bu35Game||!bu35Visible())return;
 if(!final){g.familyVoiceWins=(g.familyVoiceWins||0)+1;if(g.familyVoiceWins%2===0)return;}
 setTimeout(()=>{
  if(g!==bu35Game||!bu35Visible()||document.hidden)return;
  if(final)bu381Play('chapter_complete',{milestone:true});
  else bu381Play('excellent_thinking',{milestone:true});
 },final?250:650);
}
