 bu35El().querySelectorAll('[data-answer]').forEach(x=>x.onclick=()=>{if(g.answered)return;g.choice=+x.dataset.answer;g.answered=true;g.attempts[g.turn]++;if(g.choice===bu35Question().correct){g.scores[g.turn]+=g.hinted?50:100;g.corrects[g.turn]++;playChime();bu3829FamilyPraise(g)}else tick();bu35Save();bu35Render()});
