function bu35WheelLimit(){const g=bu35Game;return g.quick==='wheel'?999:Math.max(g.people.length,g.minutes<=10?2:g.minutes===20?3:4)}
function bu35WheelSvg(){const names=bu35Game.people,n=names.length,colors=['#98743b','#257e81','#5171aa','#8d609d','#b16b4d','#49886e'];const cx=150,cy=150,r=136;
 let wedges='';for(let i=0;i<n;i++){
 const a=(i*360/n-90)*Math.PI/180,b=((i+1)*360/n-90)*Math.PI/180,m=((i+.5)*360/n-90)*Math.PI/180;
 const sx=cx+r*Math.cos(a),sy=cy+r*Math.sin(a),ex=cx+r*Math.cos(b),ey=cy+r*Math.sin(b);
 const x=cx+87*Math.cos(m),y=cy+87*Math.sin(m);
 const name=bu35Game.people[i].length>11?bu35Game.people[i].slice(0,10)+'…':bu35Game.people[i];
 wedges+=`<path d="M150 150L${sx.toFixed(2)} ${sy.toFixed(2)}A136 136 0 ${360/n>180?1:0} 1 ${ex.toFixed(2)} ${ey.toFixed(2)}Z" fill="${colors[i%6]}" stroke="#eeddb0" stroke-width="2"/><text x="${x.toFixed(2)}" y="${y.toFixed(2)}" text-anchor="middle" dominant-baseline="middle">${bu35Escape(name)}</text>`;
 }
 return `<div class="bu35-wheel-frame"><div class="bu35-pointer" aria-hidden="true"></div><svg class="bu35-wheel" id="bu35-wheel-svg" viewBox="0 0 300 300" role="img" aria-label="Spinning wheel with family player names" style="transform:rotate(${bu35WheelAngle}deg)">${wedges}<circle cx="150" cy="150" r="34" fill="#f0d291" stroke="#8e6b37" stroke-width="3"/><text x="150" y="150" text-anchor="middle" dominant-baseline="middle" style="fill:#1d3e44;stroke:none;font-size:12px;font-weight:900">FAMILY</text></svg></div>`;
}
