 if(sfxOn&&sfxVolume>0){playChime();if(!(reduceMotion||matchMedia('(prefers-reduced-motion: reduce)').matches)){for(const ms of [110,230,365,515,680,860,1060,1290,1560,1870,2240,2670])setTimeout(()=>{if(bu35Visible()&&bu35Game===g&&bu35Phase()==='wheel'&&sfxOn)tick()},ms)}}
 const end=()=>{if(!bu35Visible()||bu35Game!==g)return;g.wheelChoice=chosen;g.wheelPrompt=bu35PickPrompt();bu35Save();bu35Render();bu35El().querySelector('.bu35-result')?.scrollIntoView({block:'center',behavior:'instant'});if(sfxOn&&sfxVolume>0)playChime()};
