 const n=(g.reflection||0),item=n%4===3?null:pool[((Number.isInteger(g.applicationOffset)?g.applicationOffset:0)+n)%pool.length];
 const intro='<div class="bu35-hero"><span class="bu35-kicker">OPEN DISCUSSION · NO SCORING</span><h2>Think About It</h2><p>Share different perspectives, or skip. There is no single required personal decision.</p></div>';
