/* Common English inflections of already approved words are valid too. The Biblical theme
   gives bonus points; it does not restrict ordinary English vocabulary. */
function wb37ValidWord(w){
 if(WB36_DICT.has(w))return true;
 const test=(base)=>base.length>=2&&WB36_DICT.has(base);
 if(w.length<3||w.length>15)return false;
 if(w.endsWith('IES')&&test(w.slice(0,-3)+'Y'))return true;
 if(w.endsWith('ES')&&/(S|SH|CH|X|Z)$/.test(w.slice(0,-2))&&test(w.slice(0,-2)))return true;
 if(w.endsWith('S')&&!w.endsWith('SS')&&test(w.slice(0,-1)))return true;
 if(w.endsWith('ED')){
  if(test(w.slice(0,-1)))return true; // LOVED -> LOVE
  if(test(w.slice(0,-2)))return true; // WALKED -> WALK
  if(w.length>4&&w[w.length-3]===w[w.length-4]&&test(w.slice(0,-3)))return true; // STOPPED -> STOP
  if(w.endsWith('IED')&&test(w.slice(0,-3)+'Y'))return true;
 }
 if(w.endsWith('ING')){
  if(test(w.slice(0,-3))||test(w.slice(0,-3)+'E'))return true;
  if(w.length>5&&w[w.length-4]===w[w.length-5]&&test(w.slice(0,-4)))return true;
 }
 return false;
}
/* v3.8.8: an independent backup protects an unfinished match if the main record cannot be read.
   Existing primary keys and serialized fields are unchanged. Neither record is deleted automatically. */
const WB388_BACKUP_KEY=WB36_KEY+'-recovery-v388';
function wb388Valid(v){
  if(!v||typeof v!=='object'||Array.isArray(v))return false;
  if(v.game==null)return !!v.setup&&Array.isArray(v.setup.people);
  const g=v.game;
  return Array.isArray(g.board)&&g.board.length===81&&Array.isArray(g.players)&&g.players.length>=1&&g.players.length<=6&&
    Array.isArray(g.rack)&&g.draft&&typeof g.draft==='object'&&!Array.isArray(g.draft)&&
    Array.isArray(g.scores)&&g.scores.length===g.players.length&&
    Number.isInteger(g.turn)&&g.turn>=0&&Number.isInteger(g.maxTurns)&&g.maxTurns>0;
}
function wb388Load(){
  for(const key of [WB36_KEY,WB388_BACKUP_KEY]){
    try{const raw=localStorage.getItem(key);if(!raw)continue;const v=JSON.parse(raw);if(wb388Valid(v))return v;}catch(_){}
  }
  return null;
}
let wb36Setup={people:['Player 1'],rounds:4,strategy:'relaxed'}; let wb36Game=null,wb36View='hub',wb36Selected=null,wb36Message='',wb36IsPreview=false;
{
  const v=wb388Load();
  if(v){if(Array.isArray(v.setup?.people))wb36Setup={...wb36Setup,...v.setup};if(v.game)wb36Game=v.game;}
}
const wb36Screen=()=>document.getElementById('wb36'); const wb36Body=()=>document.getElementById('wb36-main'); const wb36Visible=()=>!wb36Screen().hidden;
function wb36Save(){
  let payload;try{payload=JSON.stringify({setup:wb36Setup,game:wb36Game})}catch(_){return}
  try{localStorage.setItem(WB388_BACKUP_KEY,payload)}catch(_){}
  try{localStorage.setItem(WB36_KEY,payload)}catch(_){}
}
function wb36FocusTop(){wb36Body().scrollTop=0}
function wb36Open(view='hub'){
 startAudio();hideAll();closeMenu();closeDialog();stopWatch();wb36Screen().hidden=false;wb36View=view;wb36Selected=null;wb36Render();updateMusicState();
}
function wb36Exit(){wb36Save();focusHome();updateMusicState()}
function wb36Home(){wb36View='hub';wb36Render()}
function wb36Pause(){wb36View='pause';wb36Render()}
function wb36Back(){if(wb36View==='game')wb36Pause();else if(wb36View==='pause'){wb36View='game';wb36Render()}else if(wb36View==='setup'||wb36View==='help')wb36Home();else wb36Exit()}
function wb36Render(){if(!wb36Visible())return;document.getElementById('wb36-title').textContent=wb36View==='game'?'Word Builder':wb36View==='setup'?'Word Builder · Players':'Word Builder';
 const b=wb36Body(),prevScroll=b.scrollTop;if(wb36View==='hub')wb36HubUI(b);else if(wb36View==='setup')wb36SetupUI(b);else if(wb36View==='pause')wb36PauseUI(b);else if(wb36View==='help')wb36HelpUI(b);else if(wb36View==='game')wb36GameUI(b);b.scrollTop=wb36View==='game'&&wb36Game&&!wb36Game.handoff?prevScroll:0;}
function wb36HubUI(b){b.innerHTML=`<div class="wb36-hero"><span class="wb36-sub">NEW · WORD STRATEGY</span><h2>Word Builder</h2><p>Place letter tiles on a shared board. Connect words, discover bonuses, and outscore your friends.</p><button class="wb36-btn wb36-block" id="wb36-new">✦ New Game</button></div>
 ${wb36Game&&!wb36Game.finished?`<div class="wb36-card"><h3>Continue your game</h3><p>${wb36Game.players.length===1?'Solo Challenge':wb36Game.players.length+'-player Pass & Play'} · Turn ${wb36Game.turn+1}/${wb36Game.maxTurns}</p><button class="wb36-btn wb36-block" id="wb36-resume">▶ Resume Game</button></div>`:''}
 <div class="wb36-card"><h3>How It Works</h3><p>Build connected English words across and down. Bible words have bonus points, and the letters often give you a Bible-word opportunity.</p><div class="wb36-row"><button id="wb36-how" class="wb36-outline">? Rules & Tips</button><button id="wb36-solo" class="wb36-outline">▶ Solo Challenge</button></div></div><p class="wb36-foot">All words are validated offline. No online accounts required.</p>`;
 b.querySelector('#wb36-new').onclick=()=>{wb36View='setup';wb36Render()};b.querySelector('#wb36-how').onclick=()=>{wb36View='help';wb36Render()};b.querySelector('#wb36-solo').onclick=()=>{wb36Setup.people=['You'];wb36View='setup';wb36Render()};
 b.querySelector('#wb36-resume')?.addEventListener('click',()=>{wb36View='game';wb36Render()});}
function wb36SetupUI(b){const s=wb36Setup;b.innerHTML=`<div class="wb36-hero"><span class="wb36-sub">SOLO OR PASS & PLAY</span><h2>Who's Playing?</h2><p>One person can chase a score. Up to six can compete on the same board.</p></div>
 <div class="wb36-card"><div class="wb36-label">PLAYERS</div><div class="wb36-counter"><button id="wb36-minus" aria-label="Remove player" ${s.people.length<=1?'disabled':''}>−</button><strong>${s.people.length}</strong><button id="wb36-plus" aria-label="Add player" ${s.people.length>=6?'disabled':''}>+</button></div><div class="wb36-setup-grid">${s.people.map((n,i)=>`<input class="wb36-input" data-wb-name="${i}" aria-label="Player ${i+1} name" maxlength="20" value="${WB36_ESC(n)}">`).join('')}</div><label class="wb36-label" for="wb36-rounds">TURNS PER PLAYER</label><select class="wb36-input" id="wb36-rounds"><option value="3" ${s.rounds===3?'selected':''}>3 — Quick Match</option><option value="4" ${s.rounds===4?'selected':''}>4 — Standard Match</option><option value="6" ${s.rounds===6?'selected':''}>6 — Long Match</option></select><label class="wb36-label" for="wb380-strategy">LETTER CHALLENGE</label><select class="wb36-input" id="wb380-strategy"><option value="relaxed" ${!s.strategy||s.strategy==='relaxed'?'selected':''}>Relaxed · more Bible-word opportunities</option><option value="balanced" ${s.strategy==='balanced'?'selected':''}>Balanced · some helpful racks</option><option value="master" ${s.strategy==='master'?'selected':''}>Master · natural letter draws</option></select><p class="wb36-notice">Letter challenge changes how racks are drawn, not the word rules or score multipliers. Each turn gets seven tiles. Pass & Play players all use the same challenge.</p><button class="wb36-btn wb36-block" id="wb36-begin">Begin Match →</button></div>`;
 b.querySelectorAll('[data-wb-name]').forEach(x=>x.oninput=()=>{s.people[+x.dataset.wbName]=x.value;wb36Save()});b.querySelector('#wb36-minus').onclick=()=>{if(s.people.length>1)s.people.pop();wb36Save();wb36Render()};b.querySelector('#wb36-plus').onclick=()=>{if(s.people.length<6)s.people.push('Player '+(s.people.length+1));wb36Save();wb36Render()};b.querySelector('#wb36-rounds').onchange=e=>{s.rounds=+e.target.value;wb36Save()};b.querySelector('#wb380-strategy').onchange=e=>{s.strategy=e.target.value;wb36Save()};b.querySelector('#wb36-begin').onclick=wb36Begin;}
function wb36Sample(){const s=WB36_SEEDS[Math.floor(Math.random()*WB36_SEEDS.length)];const arr=s.split('');while(arr.length<7)arr.push(WB36_POOL[Math.floor(Math.random()*WB36_POOL.length)]);for(let i=arr.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]]}return arr.map((letter,i)=>({id:Date.now()+'-'+Math.random().toString(36).slice(2,8)+'-'+i,letter}));}
/* v3.6.3 — Bible-Smart Tiles.
   Approximately 76% of new racks TRY to include the letters for a legal Bible-bonus
   move on the CURRENT board. Non-Bible words stay valid and ordinary racks remain.
   The same draw logic applies to solo and every Pass & Play participant.
   Saved v3.6 games keep their board, scores and current tiles. */
const WB363_BIBLE_RACK_CHANCE=.76;
function wb363LegalTargets(g){
 if(!g||!Array.isArray(g.board)||g.board.length!==81)return [];
 const blank=g.board.every(c=>!c),used=new Set(g.bibleTargetHistory||[]);
 const source=Object.keys(WB362_BIBLE_INFO).filter(w=>w.length>=3&&w.length<=9&&(blank?w.length<=7:true));
 // Fisher–Yates instead of sort(Math.random): unbiased ordering for candidates.
 for(let i=source.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[source[i],source[j]]=[source[j],source[i]]}
 // Prioritize fresh words, then at least two newly played tiles.
 source.sort((a,b)=>Number(used.has(a))-Number(used.has(b)));
 const possibilities=[];
 for(const word of source){
  for(const step of [1,9]){
   for(let row=0;row<9;row++)for(let col=0;col<9;col++){
    if((step===1&&col+word.length>9)||(step===9&&row+word.length>9))continue;
    const draft={},needed=[];let attached=false,okay=true;
    for(let k=0;k<word.length;k++){
     const ix=row*9+col+k*step,letter=word[k],existing=g.board[ix];
     if(existing){if(existing!==letter){okay=false;break}attached=true;continue}
     if(needed.length>=7){okay=false;break}
     // A new letter also counts as attached if it touches an established tile.
     if(!blank){const y=Math.floor(ix/9),x=ix%9;
      if((x>0&&g.board[ix-1])||(x<8&&g.board[ix+1])||(y>0&&g.board[ix-9])||(y<8&&g.board[ix+9]))attached=true;
     }
     needed.push(letter);draft[ix]={letter};
    }
    if(!okay||needed.length===0||(blank&&!draft[40])||(!blank&&!attached))continue;
    // Crucial: crosswords formed sideways must ALSO be dictionary-valid.
    const result=wb36Check({...g,draft});
    if(!result.ok||!result.bonus.includes(word))continue;
    possibilities.push({word,needed});
    // Enough variety without large delays after a crowded board develops.
    if(possibilities.length>=18)break;
   }
   if(possibilities.length>=18)break;
  }
  if(possibilities.length>=18)break;
 }
 return possibilities;
}
/* Natural, balanced racks never deliberately spell out a seed answer.
   Two vowels and two consonants avoid the most frustrating impossible starts.
   This does not guarantee that a move exists on every crowded board. */
function wb380NaturalRack(){
 let letters=[];
 for(let attempt=0;attempt<16;attempt++){
  letters=Array.from({length:7},()=>WB36_POOL[Math.floor(Math.random()*WB36_POOL.length)]);
  const vowels=letters.filter(c=>'AEIOU'.includes(c)).length;
  if(vowels>=2&&vowels<=4)break;
 }
 if(letters.includes('Q')&&!letters.includes('U'))letters[letters.indexOf('Q')]='U';
 let vowelCount=letters.filter(c=>'AEIOU'.includes(c)).length;
 while(vowelCount<2){const k=letters.findIndex(c=>!'AEIOU'.includes(c));letters[k]='E';vowelCount++}
 return letters.map((letter,i)=>({id:Date.now()+'-'+Math.random().toString(36).slice(2,8)+'-'+i,letter}));
}
function wb380Strategy(g){return ['relaxed','balanced','master'].includes(g.strategy)?g.strategy:'relaxed'}
function wb363SmartRack(g){
 // A fresh rack can still have ordinary letters. Never promise a Bible word
 // if the current board cannot accommodate one without an invalid crossing.
 const difficulty=wb380Strategy(g);
 if(Math.random()>=(difficulty==='relaxed'?.76:difficulty==='balanced'?.28:0))return difficulty==='relaxed'?wb36Sample():wb380NaturalRack();
 const targets=wb363LegalTargets(g);
 if(!targets.length)return difficulty==='relaxed'?wb36Sample():wb380NaturalRack();
 const fresh=targets.filter(t=>t.needed.length>=2);
 const candidates=fresh.length?fresh:targets;
 const target=candidates[Math.floor(Math.random()*Math.min(candidates.length,10))];
 const letters=target.needed.slice();
 while(letters.length<7)letters.push(WB36_POOL[Math.floor(Math.random()*WB36_POOL.length)]);
 for(let i=letters.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[letters[i],letters[j]]=[letters[j],letters[i]]}
 g.bibleTargetHistory=(g.bibleTargetHistory||[]).concat(target.word).slice(-18);
 return letters.map((letter,i)=>({id:Date.now()+'-'+Math.random().toString(36).slice(2,8)+'-'+i,letter}));
}
function wb36Begin(){if(wb36Game&&!wb36Game.finished&&!confirm('This will replace your saved Word Builder game. Begin a new match?'))return;
 const names=wb36Setup.people.map((n,i)=>n.trim()||'Player '+(i+1));const maxTurns=names.length===1?Math.max(8,wb36Setup.rounds*2+2):names.length*wb36Setup.rounds;
 wb36Game={board:Array(81).fill(null),players:names,scores:names.map(()=>0),maxTurns,turn:0,rack:[],draft:{},exchangeUsed:false,handoff:names.length>1,finished:false,lastWords:[],mode:names.length===1?'solo':'pass',strategy:wb36Setup.strategy||'relaxed',created:Date.now()};wb36Game.rack=wb363SmartRack(wb36Game);wb36Selected=null;wb36Message='';wb36View='game';wb36Save();wb36Render()}
function wb36PlayerIndex(g){return g.turn%g.players.length}
function wb36Scores(g){return `<div class="wb36-players wb37-mini-players">${g.players.map((name,i)=>`<div class="wb36-player ${i===wb36PlayerIndex(g)?'active':''}"><b>${WB36_ESC(name)}</b><small>${g.scores[i]} pts</small></div>`).join('')}</div>`}
function wb36PauseUI(b){const g=wb36Game;b.innerHTML=`<div class="wb36-hero"><span class="wb36-sub">PAUSED</span><h2>Match Saved</h2><p>${g?g.players.length+' player'+(g.players.length!==1?'s':'')+' · turn '+(g.turn+1)+' of '+g.maxTurns:'Your game'}</p></div><button class="wb36-btn wb36-block" id="wb36-continue">▶ Resume This Turn</button><button class="wb36-outline wb36-block" id="wb36-home">‹ Word Builder Home</button><button class="wb36-ghost wb36-block" id="wb36-mainhome">Return to Main Menu</button>`;b.querySelector('#wb36-continue').onclick=()=>{wb36View='game';wb36Render()};b.querySelector('#wb36-home').onclick=wb36Home;b.querySelector('#wb36-mainhome').onclick=wb36Exit}
function wb36HelpUI(b){b.innerHTML=`<div class="wb36-hero"><span class="wb36-sub">GAME GUIDE</span><h2>Learn Word Builder</h2></div><div class="wb36-card wb36-help"><p><strong>1.</strong> Tap a rack tile, then an empty board square. Tap a glowing provisional tile to take it back.</p><p><strong>2.</strong> The first word must cross the ★ center. Later words must connect with existing letters. Place new letters in one straight line, without gaps.</p><p><strong>3.</strong> Every resulting word (across and down) must be valid and at least two letters long.</p><p><strong>4.</strong> 2× and 3× spaces increase the value of letters newly placed on them. A curated Bible-theme word adds 12 points. When a small gold ✦ appears by your score, tap it for an optional Bible clue. Use all seven tiles for a bonus.</p><p><strong>5.</strong> Each player gets seven fresh tiles per turn. Idea is a free move suggestion, shown as pending tiles you can recall. Exchange costs 20 Insight Tokens, ends your turn, and saves the new rack for your next turn. The score preview shows all word and Bible bonuses before Play Word.</p><p><strong>6.</strong> In multiplayer, pass the phone when the new name appears. The next rack stays hidden until Ready is tapped.</p><p>Solo Challenge includes Bronze, Silver, and Gold score goals. In Pass & Play, human players share the phone; there is no computer opponent. You can pause and resume either mode.</p><button class="wb36-btn wb36-block" id="wb36-helpend">Got It ✓</button></div>`;b.querySelector('#wb36-helpend').onclick=()=>{wb36View='hub';wb36Render()}}
function wb36RenderCell(g,i){const draft=g.draft[i],occupied=g.board[i],letter=draft?.letter||occupied;
 const css=occupied?'filled':draft?'filled draft':i===40?'center':WB36_BONUS3.has(i)?'bonus3':WB36_BONUS2.has(i)?'bonus2':'';
 const show=letter|| (i===40?'★':WB36_BONUS3.has(i)?'3×':WB36_BONUS2.has(i)?'2×':'');
 return `<button class="wb36-cell ${css}" data-wb-cell="${i}" aria-label="Row ${Math.floor(i/9)+1}, column ${i%9+1}${letter?', letter '+letter:''}${draft?', pending':''}" ${occupied?'disabled':''}>${show}</button>`;
}
function wb36GuideSeen(){try{return !!localStorage.getItem('bible-unfolded-wb36-guide')}catch(_){return true}}
/* A discovery indicator appears ONLY when the current rack and board allow
   a real, legal move worth a Bible-word bonus. No free guesses or spoilers. */
function wb362FindDiscovery(g){
 if(!g||g.handoff||g.finished||Object.keys(g.draft).length)return null;
 const rackLetters=g.rack.map(t=>t.letter),empty=g.board.every(v=>!v);
 for(const word of Object.keys(WB362_BIBLE_INFO)){
  if(word.length>9||word.length<2)continue;
  for(const step of [1,9])for(let row=0;row<9;row++)for(let col=0;col<9;col++){
   if(step===1&&col+word.length>9||step===9&&row+word.length>9)continue;
   const remaining=rackLetters.slice(),draft={};let placed=0,okay=true;
   for(let k=0;k<word.length;k++){
    const i=row*9+col+k*step,ch=word[k];
    if(g.board[i]){if(g.board[i]!==ch){okay=false;break}}
    else{const ri=remaining.indexOf(ch);if(ri<0){okay=false;break}remaining.splice(ri,1);draft[i]={letter:ch};placed++}
   }
   if(!okay||!placed||placed>g.rack.length)continue;
   // First word must use center, later words must truly connect, and EVERY cross must be valid.
   if(empty&&!Object.hasOwn(draft,40))continue;
   const check=wb36Check({...g,draft});
   if(check.ok&&check.bonus.includes(word))return word;
  }
 }
 return null;
}
function wb362ShowClue(b,word){
 const info=WB362_BIBLE_INFO[word];if(!info)return;
 const shade=document.createElement('div');shade.className='wb37-guide-shade wb362-discovery-shade';
 shade.innerHTML=`<div class="wb37-guide" role="dialog" aria-modal="true" aria-label="Bible word clue"><div class="wb36-sub">✦ BIBLE WORD OPPORTUNITY</div><h2>There's a discovery nearby!</h2><p>${WB36_ESC(info[0])}</p><p style="font-size:12px">Clue inspired by ${WB36_ESC(info[1])}. Solve it on the board for +12 bonus points.</p><button class="wb36-btn wb36-block" id="wb362-clue-close">Back to Board ✓</button><button class="wb36-ghost wb36-block" id="wb362-clue-off">Turn off Bible clues</button></div>`;
 wb36Screen().appendChild(shade);
 shade.querySelector('#wb362-clue-close').onclick=()=>shade.remove();
 shade.querySelector('#wb362-clue-off').onclick=()=>{try{localStorage.setItem('bible-unfolded-wb362-clues-off','1')}catch(_){}shade.remove();wb36Render()};
}
function wb362ClueEnabled(){try{return !localStorage.getItem('bible-unfolded-wb362-clues-off')}catch(_){return true}}
function wb380SoloGoals(g){const t=g.maxTurns||10;return {bronze:t*10,silver:t*15,gold:t*21}}
function wb380GoalMark(g){if(g.players.length!==1)return '';
 const goals=wb380SoloGoals(g),score=g.scores[0],next=score<goals.bronze?goals.bronze:score<goals.silver?goals.silver:goals.gold;
 const tier=score>=goals.gold?'Gold':score>=goals.silver?'Silver':score>=goals.bronze?'Bronze':'Building';
 const pct=Math.min(100,Math.round(score/goals.gold*100));
 return `<div class="wb380-goal" aria-label="Solo goal progress"><span>${tier==='Building'?'Your challenge':tier+' achieved'} · ${score} / ${goals.gold} Gold</span><div class="wb380-goal-track"><i style="width:${pct}%"></i></div><small>Bronze ${goals.bronze} · Silver ${goals.silver} · Gold ${goals.gold}</small></div>`;
}
function wb380ScorePreview(check){
 if(!check)return '';
 if(!check.ok)return `<div class="wb380-preview wb380-preview-note" role="status"><span>Building a word</span><small>${WB36_ESC(check.reason)}</small></div>`;
 const item=check.breakdown.map(x=>`${WB36_ESC(x.word)} ${x.letters}${x.bible?` +12 Bible`:''}`).join(' · ');
 return `<div class="wb380-preview" role="status"><strong>Potential +${check.points} points</strong><small>${item}${check.allTilesBonus?' · +25 seven-tile bonus':''}</small></div>`;
}
function wb36GameUI(b){const g=wb36Game;if(!g){wb36Home();return}if(g.finished){wb36ResultsUI(b);return}
 if(g.handoff){b.innerHTML=`${wb36Scores(g)}<div class="wb36-card wb36-handoff"><span class="wb36-sub">PASS THE PHONE · TURN ${g.turn+1}/${g.maxTurns}</span><h2>${WB36_ESC(g.players[wb36PlayerIndex(g)])}</h2><p>Take the phone and get ready to build. Your tiles are hidden until you begin.</p><button class="wb36-btn wb36-block" id="wb36-ready">I'm Ready →</button></div><button class="wb36-ghost wb36-block" id="wb36-save">Save & Leave</button>`;b.querySelector('#wb36-ready').onclick=()=>{g.handoff=false;wb36Save();wb36Render()};b.querySelector('#wb36-save').onclick=wb36Pause;return}
 const available=wb362ClueEnabled()?wb362FindDiscovery(g):null;const draftScore=Object.keys(g.draft).length?wb36Check(g):null;
 b.innerHTML=`<div class="wb37-scorebar"><span>Turn ${g.turn+1}/${g.maxTurns} · ${wb380Strategy(g)==='master'?'Master':wb380Strategy(g)==='balanced'?'Balanced':'Relaxed'}</span><strong>${g.players.length===1?`✦ ${g.scores[0]} pts`:`${WB36_ESC(g.players[wb36PlayerIndex(g)])} · ${g.scores[wb36PlayerIndex(g)]} pts`}</strong>${available?'<button class="wb362-clue-indicator" id="wb362-clue" aria-label="A Bible bonus word can be played. Show clue" title="Bible bonus word nearby">✦</button>':''}<button class="wb37-help" id="wb37-help" aria-label="Word Builder instructions">?</button></div>${g.players.length>1?wb36Scores(g):wb380GoalMark(g)}
 <div class="wb36-board" role="group" aria-label="Nine by nine word building board">${g.board.map((_,i)=>wb36RenderCell(g,i)).join('')}</div>
 <div class="wb36-rack" role="group" aria-label="Your seven letter tiles">${g.rack.map(t=>`<button class="wb36-tile ${wb36Selected===t.id?'selected':''}" data-wb-tile="${t.id}" aria-label="Tile ${t.letter} worth ${WB36_POINTS[t.letter]||1} points">${t.letter}<small>${WB36_POINTS[t.letter]||1}</small></button>`).join('')}</div>
 ${wb380ScorePreview(draftScore)}<div class="wb36-status ${wb36Message?'has-message':''}" role="status">${WB36_ESC(wb36Message)}</div>
 <div class="wb37-actions"><button class="wb36-btn wb36-primary" id="wb36-submit" ${Object.keys(g.draft).length?'':'disabled'}>✓ Play Word</button><div class="wb37-tools"><button class="wb36-outline" id="wb36-try" aria-label="Suggest a free word (never costs Insight Tokens)">✦ Idea</button><button class="wb36-outline" id="wb36-undo" ${Object.keys(g.draft).length?'':'disabled'} aria-label="Recall pending tiles">↶ Undo</button><button class="wb36-outline" id="wb36-mix" aria-label="Shuffle letters">⤨ Mix</button><button class="wb36-outline" id="wb37-more" aria-expanded="false" aria-controls="wb37-extra">⋯ More</button></div><div id="wb37-extra" class="wb37-extra" hidden><button class="wb36-outline" id="wb36-exchange" ${g.exchangeUsed?'disabled':''}>⇄ Exchange · 20 Insight Tokens, ends turn</button><button class="wb36-ghost" id="wb36-pass">Pass Turn →</button></div></div>`;
 b.querySelectorAll('[data-wb-tile]').forEach(x=>{
 x.onclick=()=>{if(x.dataset.dragWas){delete x.dataset.dragWas;return}wb36Selected=wb36Selected===x.dataset.wbTile?null:x.dataset.wbTile;wb36Message='';wb36Render()};
 let pid=null,sx=0,sy=0,drag=false,ghost=null,lastCell=null,dropCell=null;
 // The tile floats ABOVE the fingertip, so the player can see the target cell.
 // A light travel boost means the finger covers less distance than the tile.
 const fingerGap=()=>Math.min(92,Math.max(64,window.innerHeight*.105));
 const projectedPoint=e=>({x:sx+(e.clientX-sx)*1.12,y:sy+(e.clientY-sy)*1.18-fingerGap()});
 const hitCell=p=>document.elementFromPoint(p.x,p.y)?.closest('[data-wb-cell]:not([disabled])')||null;
 const clearDrag=()=>{ghost?.remove();ghost=null;lastCell?.classList.remove('wb372-drop-target');lastCell=null;dropCell=null;drag=false;pid=null};
 x.onpointerdown=e=>{if(e.pointerType==='mouse'&&e.button!==0)return;pid=e.pointerId;sx=e.clientX;sy=e.clientY;try{x.setPointerCapture(e.pointerId)}catch(_){}};
 x.onpointermove=e=>{if(e.pointerId!==pid)return;if(!drag&&Math.hypot(e.clientX-sx,e.clientY-sy)>7){
  drag=true;ghost=x.cloneNode(true);ghost.removeAttribute('data-wb-tile');ghost.className='wb36-tile wb372-drag-ghost';document.body.appendChild(ghost);
 }if(!drag)return;e.preventDefault();const p=projectedPoint(e);
 // Use compositor-friendly transforms rather than reflowing the board on every move.
 ghost.style.transform=`translate3d(${p.x-23}px,${p.y-23}px,0) scale(1.13)`;
 const cell=hitCell(p);if(lastCell!==cell){lastCell?.classList.remove('wb372-drop-target');lastCell=cell;lastCell?.classList.add('wb372-drop-target')}dropCell=cell;
 };
 x.onpointerup=e=>{if(e.pointerId!==pid)return;if(!drag){clearDrag();return}e.preventDefault();e.stopPropagation();
 const cell=hitCell(projectedPoint(e))||dropCell;
 x.dataset.dragWas='1';setTimeout(()=>delete x.dataset.dragWas,250);
 // Prevent another render until we have a confirmed target.
 clearDrag();if(cell){wb36Selected=x.dataset.wbTile;wb36CellTap(+cell.dataset.wbCell)}
 };
 x.onpointercancel=clearDrag;
 });
 b.querySelectorAll('[data-wb-cell]').forEach(x=>x.onclick=()=>wb36CellTap(+x.dataset.wbCell));
 b.querySelector('#wb36-submit').onclick=wb36Submit;b.querySelector('#wb36-try').onclick=wb36Suggest;b.querySelector('#wb36-undo').onclick=()=>{wb36Undo();wb36Message='Tiles returned to your rack.';wb36Save();wb36Render()};b.querySelector('#wb36-mix').onclick=()=>{for(let i=g.rack.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[g.rack[i],g.rack[j]]=[g.rack[j],g.rack[i]]}wb36Selected=null;wb36Render()};b.querySelector('#wb36-exchange').onclick=()=>{const p=wb36PlayerIndex(g),cost=20;if(g.turn+g.players.length>=g.maxTurns){wb36Message='No later turn remains to use an exchanged rack. Use Pass Turn instead.';wb36Render();return}if(!confirm('Exchange your seven tiles for 20 Insight Tokens? This ends your turn. The new letters will be saved for YOUR next turn.'))return;if(!canSpend(cost,true))return;wb36Undo();g.exchangedRacks=g.exchangedRacks||{};g.exchangedRacks[p]=wb363SmartRack(g);wb36NextTurn();wb36Message='New rack ready for your next turn.';wb36Save();wb36Render()};b.querySelector('#wb36-pass').onclick=()=>{if(confirm('End this turn without scoring?'))wb36NextTurn()};b.querySelector('#wb37-more').onclick=()=>{const more=b.querySelector('#wb37-extra');more.hidden=!more.hidden;b.querySelector('#wb37-more').setAttribute('aria-expanded',String(!more.hidden))};b.querySelector('#wb37-help').onclick=()=>wb37ShowGuide(b,false);b.querySelector('#wb362-clue')?.addEventListener('click',()=>wb362ShowClue(b,available));
 if(!wb36GuideSeen())wb37ShowGuide(b,true)
}
function wb37ShowGuide(b,first){
 if(b.querySelector('.wb37-guide-shade'))return;
 const overlay=document.createElement('div');overlay.className='wb37-guide-shade';
 overlay.innerHTML=`<div class="wb37-guide" role="dialog" aria-modal="true" aria-label="Word Builder basics"><div class="wb36-sub">WORD BUILDER</div><h2>You're ready to play!</h2><p>Drag a tile onto the board, or tap a tile and then a square. The Play Word button previews valid points. Your opening word touches <strong>★</strong>. After that, connect new words to existing ones.</p><p><strong>2×</strong> and <strong>3×</strong> spaces boost scores. Bible words earn an extra bonus; other English words count too.</p><button class="wb36-btn wb36-block" id="wb37-guide-ok">Let's Play ✓</button></div>`;
 wb36Screen().appendChild(overlay);
 overlay.querySelector('button').onclick=()=>{if(first)try{localStorage.setItem('bible-unfolded-wb36-guide','1')}catch(_){};overlay.remove()};
}
function wb36CellTap(i){const g=wb36Game;if(g.board[i])return;
 if(g.draft[i]){g.rack.push(g.draft[i]);delete g.draft[i];wb36Selected=null;wb36Message='Tile returned.';wb36Save();wb36Render();return}
 if(wb36Selected===null){wb36Message='Select a tile from your rack first.';wb36Render();return}
 const k=g.rack.findIndex(t=>t.id===wb36Selected);if(k<0)return;g.draft[i]=g.rack.splice(k,1)[0];wb36Selected=null;wb36Message='';wb36Save();wb36Render();}
function wb36Undo(){const g=wb36Game;Object.values(g.draft).forEach(tile=>g.rack.push(tile));g.draft={};wb36Selected=null}
function wb36WordAt(g,i,dir){let start=i,end=i;const step=dir==='H'?1:9;const exists=k=>k>=0&&k<81&&(g.board[k]||g.draft[k]);
 const back=k=>dir==='H'?k%9>0:k>=9;const forward=k=>dir==='H'?k%9<8:k<72;
 while(back(start)&&exists(start-step))start-=step;
 while(forward(end)&&exists(end+step))end+=step;
 let w='',indices=[];for(let x=start;x<=end;x+=step){w+=(g.draft[x]?.letter||g.board[x]||'');indices.push(x)}return {word:w,start,dir,indices};}
function wb36Check(g){const positions=Object.keys(g.draft).map(Number);if(!positions.length)return {ok:false,reason:'Place at least one tile.'};
 const horizontal=positions.every(i=>Math.floor(i/9)===Math.floor(positions[0]/9));const vertical=positions.every(i=>i%9===positions[0]%9);if(!horizontal&&!vertical)return {ok:false,reason:'Place new tiles in one straight row or column.'};
 if(positions.length>1){const line=horizontal?'H':'V',step=line==='H'?1:9;for(let k=Math.min(...positions);k<=Math.max(...positions);k+=step){if(!g.draft[k]&&!g.board[k])return {ok:false,reason:'Your word has a gap. Fill it or use existing letters.'}}}
 const empty=g.board.every(x=>!x);if(empty&&!g.draft[40])return {ok:false,reason:'Your first word must cross the ★ center.'};
 if(!empty&&!positions.some(i=>[i%9>0?i-1:-1,i%9<8?i+1:-1,i-9,i+9].some(j=>j>=0&&j<81&&!!g.board[j])))return {ok:false,reason:'Connect your new letters to an existing word.'};
 const words=new Map();for(const i of positions)for(const dir of ['H','V']){const o=wb36WordAt(g,i,dir);if(o.word.length>=2)words.set(dir+'-'+o.start,o)}if(!words.size)return {ok:false,reason:'Build a word at least two letters long.'};
 for(const o of words.values())if(!wb37ValidWord(o.word))return {ok:false,reason:'“'+o.word+'” isn’t in this game’s dictionary yet. Try another word.'};
 let points=0,bonus=[],breakdown=[];
 for(const o of words.values()){
  let lettersScore=0;
  for(const i of o.indices){const l=g.draft[i]?.letter||g.board[i];lettersScore+=(WB36_POINTS[l]||1)*(g.draft[i]?(WB36_BONUS3.has(i)?3:WB36_BONUS2.has(i)?2:1):1)}
  const bibleBonus=WB36_BIBLE.has(o.word)?12:0;
  if(bibleBonus)bonus.push(o.word);
  points+=lettersScore+bibleBonus;
  breakdown.push({word:o.word,letters:lettersScore,bible:bibleBonus,total:lettersScore+bibleBonus});
 }
 const allTilesBonus=positions.length===7?25:0;
 points+=allTilesBonus;
 return {ok:true,points,words:breakdown.map(x=>x.word),bonus,breakdown,allTilesBonus};}
function wb372NextRack(g){const p=wb36PlayerIndex(g),held=g.exchangedRacks?.[p];if(held?.length){delete g.exchangedRacks[p];return held}return wb363SmartRack(g)}
function wb36Submit(){const g=wb36Game,check=wb36Check(g);if(!check.ok){wb36Message=check.reason;playFx('tap',.25);wb36Render();return}
 for(const [i,t] of Object.entries(g.draft))g.board[+i]=t.letter;
 const p=wb36PlayerIndex(g);g.scores[p]+=check.points;g.lastWords=check.words;g.lastPoints=check.points;g.draft={};wb36Selected=null;playChime();if(check.points>=30)playCoinFx('earn');wb36Message=`${check.words.join(' + ')} · +${check.points} pts${check.bonus.length?' · ✦ Bible bonus +12':''}`;g.bibleLast=check.bonus.find(w=>WB362_BIBLE_INFO[w])||null;
 g.turn++;if(g.turn>=g.maxTurns)wb36Complete();else{g.rack=wb372NextRack(g);g.exchangeUsed=false;g.handoff=g.players.length>1;g.justPlayed=true}wb36Save();if(g.finished)bu34Celebrate('WORD BUILDER COMPLETE!',true);wb36Render();}
function wb36NextTurn(){const g=wb36Game;wb36Undo();g.turn++;wb36Message='';if(g.turn>=g.maxTurns)wb36Complete();else{g.rack=wb372NextRack(g);g.exchangeUsed=false;g.handoff=g.players.length>1}wb36Save();wb36Render()}
function wb36Complete(){const g=wb36Game;g.finished=true;g.draft={};g.handoff=false;const used=g.board.filter(Boolean).length;if(used>=6){const id=g.mode==='solo'?'builder-v36-solo':'builder-v36-pass';if(!g.rewarded){awardOnce(id,g.mode==='solo'?120:150,g.mode==='solo'?30:35,true);g.rewarded=true}}}
function wb36ResultsUI(b){const g=wb36Game;const ranking=g.players.map((name,i)=>({name,score:g.scores[i]})).sort((a,b)=>b.score-a.score);b.innerHTML=`<div class="wb36-hero"><span class="wb36-sub">MATCH COMPLETE</span><h2>${g.mode==='solo'?'Your Word Adventure':'Well Played, Everyone!'}</h2><p>${g.mode==='solo'?`You scored ${g.scores[0]} points in ${g.maxTurns} turns. ${g.scores[0]>=wb380SoloGoals(g).gold?'Gold target reached!':g.scores[0]>=wb380SoloGoals(g).silver?'Silver target reached!':g.scores[0]>=wb380SoloGoals(g).bronze?'Bronze target reached!':'Keep practicing to reach Bronze.'}`:'One shared board, plenty of clever words.'}</p></div><div class="wb36-card"><h3>${g.mode==='solo'?'Final Score':'Leaderboard'}</h3><div class="wb36-scores">${ranking.map((x,i)=>`<div class="wb36-scoreline"><span>${i===0?'★ ':''}${WB36_ESC(x.name)}</span><span>${x.score} pts</span></div>`).join('')}</div><p>${g.rewarded?'First-time completion reward checked. Replays never award it again.':'Play more tiles to qualify for a first-time completion bonus.'}</p></div><div class="wb36-row"><button class="wb36-btn" id="wb36-again">↻ Play Again</button><button class="wb36-outline" id="wb36-done">Return to Word Builder</button></div>`;b.querySelector('#wb36-again').onclick=()=>{wb36Game=null;wb36Begin()};b.querySelector('#wb36-done').onclick=()=>{wb36Game=null;wb36Save();wb36Home()}}
function wb36Suggest(){const g=wb36Game;if(Object.keys(g.draft).length){wb36Message='Recall your pending tiles before trying a suggested move.';wb36Render();return}
 const boardEmpty=g.board.every(x=>!x),candidates=Object.keys(WB362_BIBLE_INFO).concat(WB36_SEEDS).concat('ARE ART EAR EAT ERA OAR OAT OUR OUT RAT RAN RAN RAY RED ROW SAD SAT SEA SEE SET SHE SIT SON SUN TAR TEA TEN THE TIE TIN TOE TOP TWO USE VAN WAR WAS WAY WEAR WET WHO WIN WON YES YET YOU YOUR YEAR NEAR LATE RATE STAR STARE TEAR TARE TEAM MEAT HEAR HEAT HER HAT HEN HOP HOT HUT INK ICE KEY LAW LAY LET LIE LIP LOW MAN MAP MAT MEN MET NEW NET NOSE NOT OIL OLD ONE OPEN ORANGE ORE OVEN OWL PAN PART PAST PAT PAY PEN PET PIE PIN PIT POT RACE RAIN RAN RANK RAP RAW RAY READ RED RICE RIDE RING RISE ROAD ROB ROCK ROLE ROPE ROSE ROW RUG RUN SAFE SAGE SAIL SALE SALT SAME SAND SAVE SAW SAY SEAT SEE SEED SEEK SEEM SEEN SELF SEND SENT SET SEW SHIP SHOE SHOP SHOT SHOW SIDE SIGN SILK SING SINK SIR SIT SIX SIZE SKIN SKY SLEEP SLIDE SLOW SOAP SOIL SOLD SOLE SOME SONG SOON SORT SOUL SOUP SOUR SOUTH SPAN SPIN SPOT STAND STAR START STAY STEP STOP STORE STORM STORY STUDY SUM SUN SUNK SURE SWIM SWING TABLE TAKE TALE TALK TALL TAME TANK TAPE TASK TASTE TAX TEACH TEAR TELL TEN TEND TERM TEST THAN THANK THAT THEM THEN THERE THESE THEY THICK THIN THING THINK THIS THOSE THREE THROW TIDE TIED TILL TIME TINY TIRE TOAD TOAST TODAY TOLD TONE TOOL TOP TOTAL TOUCH TOUR TOWN TOY TRAIL TRAIN TRAP TREE TRIP TRUE TRY TUBE TUNE TURN TWIN TYPE UNIT UPON URGE USE USER VAST VERY VEST VIEW VINE VOTE WAIT WAKE WALK WALL WANT WARM WASH WASTE WATCH WAVE WAY WE WEAR WEEK WELL WENT WERE WEST WHAT WHEAT WHEN WHERE WHICH WHILE WHITE WHOLE WIDE WIFE WILD WILL WIND WINE WING WINK WIRE WISE WISH WITH WOLF WOMAN WON WORD WORK WORLD WORRY WORTH WOULD WRITE YEAR YELL YET YIELD YOUNG ZERO ZONE'.split(' ')).filter((w,i,a)=>w.length<=8&&a.indexOf(w)===i&&WB36_DICT.has(w));
 let best=null,bestPoints=-1;
 for(const word of candidates){if(word.length<2||word.length>8)continue;for(let dir=0;dir<2;dir++){const step=dir?9:1;for(let row=0;row<9;row++)for(let col=0;col<9;col++){
 if((dir?row+word.length>9:col+word.length>9))continue;
 const start=row*9+col,remaining=g.rack.map(t=>({...t})),draft={};let okay=true,added=0;
 for(let j=0;j<word.length;j++){const ix=start+j*step;if(g.board[ix]){if(g.board[ix]!==word[j]){okay=false;break}}else{const index=remaining.findIndex(t=>t.letter===word[j]);if(index<0){okay=false;break}draft[ix]=remaining.splice(index,1)[0];added++}}
 if(!okay||added===0||added>7)continue;
 const result=wb36Check({...g,draft});if(result.ok&&result.points>bestPoints){best={draft,remaining,word,points:result.points};bestPoints=result.points;if(bestPoints>35)break}
 }}}
 if(best){g.draft=best.draft;g.rack=best.remaining;wb36Selected=null;wb36Message='';wb36Save();wb36Render()}else{wb36Message='No legal suggestion found in this quick search. You can still try your own word, Exchange, or Pass Turn.';wb36Render()}}
