function wb36FamilyPauseUI(b){const g=bu35Game;b.innerHTML=`<div class="bu35-hero"><span class="bu35-kicker">SESSION PAUSED</span><h2>You're Still Here!</h2><p>${g?bu35Escape(BU35_TOPICS[g.topic]?.name||'Family Worship')+' · '+(g.phase+1)+' of '+g.phases.length:'Family Worship'}</p></div><div class="bu35-card"><h3>What would you like to do?</h3><button class="bu35-btn" id="wb36-family-resume">▶ Resume This Activity</button><button class="bu35-outline" id="wb36-family-hub" style="width:100%;margin-top:10px">⌂ Family Worship Home</button><button class="bu35-soft" id="wb36-family-main">Return to Main Menu</button><p>Your turn, answers, and session progress are saved.</p></div>`;
 b.querySelector('#wb36-family-resume').onclick=()=>{bu35View='game';bu35Render()};b.querySelector('#wb36-family-hub').onclick=bu35Hub;b.querySelector('#wb36-family-main').onclick=bu35Exit;}
const wb36FamilyRender=bu35Render;bu35Render=function(){if(bu35View==='pause'&&bu35Visible()){document.getElementById('bu35-title').textContent='Family Worship · Paused';wb36FamilyPauseUI(bu35El());bu35El().scrollTop=0;return}wb36FamilyRender()};
document.getElementById('bu35-back').onclick=()=>{if(bu35View==='game'){clearTimeout(bu35SpinTimer);bu35Save();bu35View='pause';bu35Render()}else if(bu35View==='pause'){bu35View='game';bu35Render()}else if(bu35View==='setup')bu35Hub();else bu35Exit()};
// Browser Back: preserve local session rather than navigating away by accident.
let wb36HistoryArmed=false;function wb36ArmBack(){try{history.pushState({bu36Overlay:true},'',location.href);wb36HistoryArmed=true}catch(_){}}
