const wb36OldFamilyOpen=bu35Open;bu35Open=function(view='hub'){wb36OldFamilyOpen(view);wb36ArmBack()};
window.addEventListener('popstate',()=>{if(wb36Visible()){if(wb36View==='game')wb36Pause();else if(wb36View==='pause')wb36Home();else wb36Exit();wb36ArmBack()}else if(bu35Visible()){if(bu35View==='game'){bu35Save();bu35View='pause';bu35Render()}else if(bu35View==='pause')bu35Hub();else if(bu35View==='setup')bu35Hub();else bu35Exit();wb36ArmBack()}});
