function v37TapTone(big=false){
 if(!sfxOn||sfxVolume<=0||!big)return;
 try{const ac=v37SfxContext||(v37SfxContext=new (window.AudioContext||window.webkitAudioContext)());if(ac.state==='suspended')ac.resume();
  const now=ac.currentTime;const volume=Math.min(.045,.028*sfxVolume/100);
  [0, .07, .14].forEach((delay,i)=>{const osc=ac.createOscillator(),gain=ac.createGain();osc.type='sine';osc.frequency.setValueAtTime([523.25,659.25,783.99][i],now+delay);gain.gain.setValueAtTime(.0001,now+delay);gain.gain.exponentialRampToValueAtTime(volume,now+delay+.02);gain.gain.exponentialRampToValueAtTime(.0001,now+delay+.21);osc.connect(gain);gain.connect(ac.destination);osc.start(now+delay);osc.stop(now+delay+.23)});
 }catch(_){}}
function v37Spark(x,y,count=9){if(reduceMotion||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const layer=document.body;for(let i=0;i<count;i++){const dot=document.createElement('span'),a=Math.PI*2*i/count,dist=20+Math.random()*35;dot.className='v37-fx-dot';dot.style.left=x+'px';dot.style.top=y+'px';dot.style.width=dot.style.height=(3+Math.random()*5)+'px';dot.style.setProperty('--dx',(Math.cos(a)*dist)+'px');dot.style.setProperty('--dy',(Math.sin(a)*dist)+'px');layer.appendChild(dot);setTimeout(()=>dot.remove(),800);}}
