// On Android and iOS, preload metadata (not the full music) so the media element
// knows it has a playable MP3 before the user activates the Music checkbox.
for(const [name,file] of Object.entries(bu371TrackFiles)){
 const audio=bu25Audio[name];if(!audio)continue;
 audio.preload='metadata';
 const resolved=new URL(file,document.baseURI).href;
 if(audio.src!==resolved){audio.src=resolved;}
 audio.load();
 audio.addEventListener('playing',()=>{
  bu371Failures[name]=0;bu371Pending[name]=false;
  if(bu25Current===name){bu25Status='';bu25UpdateStatus()}
 });
 audio.addEventListener('error',()=>{
  if(bu25Current!==name||!musicOn)return;
  const code=audio.error?.code||0;
  bu25Status=bu25Labels[name]+' could not load (media error '+code+'). Tap Retry Music.';
  bu25UpdateStatus();
 });
}
const bu371OriginalStatus=bu25UpdateStatus;
bu25UpdateStatus=function(){
 bu371OriginalStatus();
 bu371RetryButton.style.display=(musicOn && !!bu25Status && !document.hidden)?'inline-block':'none';
};
// Override only the media-element play invocation, not the route, volume,
// setting, WebAudio effects or save functionality.
bu25Play=function(key){
 const audio=bu25Audio[key];
 if(!audio||!musicOn||!musicUnlocked||document.hidden||!audio.paused||bu371Pending[key])return;
 bu371Pending[key]=true;
 let result;
 try{result=audio.play()}catch(err){bu371Pending[key]=false;bu371PlayFailed(key,err);return}
 if(result && typeof result.then==='function'){
  result.then(()=>{bu371Pending[key]=false;if(bu25Current===key){bu25Status='';bu25UpdateStatus()}})
   .catch(err=>{bu371Pending[key]=false;bu371PlayFailed(key,err)});
 }else bu371Pending[key]=false;
};
function bu371PlayFailed(key,err){
 if(!musicOn||bu25Current!==key||document.hidden)return;
 if(err && err.name==='AbortError')return; // expected during a screen change or pause
 bu371Failures[key]=(bu371Failures[key]||0)+1;
 const category=err?.name||'PlaybackError';
 bu25Status=(bu25Labels[key]||'Audio')+' couldn\'t start ('+category+'). Tap Retry Music.';
 bu25UpdateStatus();
}
// Retry is a user gesture, which preserves mobile browser audio permissions.
// Re-fetch a fresh copy after a NotSupportedError without touching localStorage.
bu371RetryButton.addEventListener('click',()=>{
 const key=bu25Target(),audio=bu25Audio[key];
 if(!audio)return;
 musicUnlocked=true;
 bu371Pending[key]=false;
 if(bu371TrackFiles[key]){
  const file=bu371TrackFiles[key];
  // GitHub Pages' known project path, verified to serve the MP3 in Chrome.
  const canonical=(location.hostname==='basilejoseph325-jpg.github.io')
   ?new URL('/Story-Trails/'+file,location.origin)
   :new URL(file,document.baseURI);
  canonical.searchParams.set('audio-retry','371');
  audio.src=canonical.href;
  audio.load();
 }
 bu25Current=key;
 bu25Status='Retrying '+bu25Labels[key]+'…';
 bu25UpdateStatus();
 // play() remains inside the actual tap/click activation.
 bu25AudioPulse();bu25Play(key);
});
bu25UpdateStatus();
