// v3.7.5 Daily Discovery. All questions and source links reuse existing JW.org-grounded trivia.
// Uses new additive storage; existing chapter, coin, trivia, and audio keys are untouched.
const BU375_KEY='bible-unfolded-daily-discovery-v375';
const BU388_DAILY_BACKUP_KEY=BU375_KEY+'-recovery-v388';
function bu388DailyValid(v){
  if(!v||typeof v!=='object'||Array.isArray(v)||!v.completions||typeof v.completions!=='object'||Array.isArray(v.completions))return false;
  if(v.active==null)return true;
  const a=v.active;
  if(!a||typeof a!=='object'||!/^\d{4}-\d{2}-\d{2}$/.test(a.day)||!['reflect','deep'].includes(a.mode)||
      !Number.isInteger(a.step)||a.step<0||a.step>5||!Array.isArray(a.answers)||a.answers.length>5)return false;
  if(a.items!=null&&(!Array.isArray(a.items)||a.items.length!==5||!a.items.every(q=>
      q&&typeof q.q==='string'&&Array.isArray(q.choices)&&q.choices.length===4&&Number.isInteger(q.correct)&&q.correct>=0&&q.correct<4)))return false;
  return true;
}
function bu388LoadDaily(){
  for(const key of [BU375_KEY,BU388_DAILY_BACKUP_KEY]){
    try{const raw=localStorage.getItem(key);if(!raw)continue;const v=JSON.parse(raw);if(bu388DailyValid(v))return v;}catch(_){}
  }
  return null;
}
